/* LOF-26-RA — every chart of risque.html, drawn with D3 from window.RISK
   (risque_data.js, generated by analyse_risque.py). Analyst terminal style:
   right-hand value axes, crosshairs with axis tags, readouts in the panel header. */
(() => {
  'use strict';
  const R = window.RISK;
  const loc = d3.formatLocale({ decimal: ',', thousands: ' ', grouping: [3], currency: ['', ' €'], minus: '−' });
  const F = s => loc.format(s);
  const f0 = F(',.0f'), f1 = F('.1f'), f2 = F('.2f'), fs1 = F('+.1f'), fs0 = F('+.0f'), fs2 = F('+.2f');
  const hm = h => { const m = Math.round(h * 60); return `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')}`; };
  const root = document.querySelector('.viz-root');
  const C = n => getComputedStyle(root).getPropertyValue(n).trim();
  const $ = id => document.getElementById(id);
  const actName = id => (R.rows.find(r => r.id === id) || {}).name || id;
  const rowOf = id => R.rows.find(r => r.id === id);
  const dayLbl = d => `J${d}`;
  const dateLbl = s => { const [, m, d] = s.split('-'); return `${+d}/${m}`; };
  const GL = { 1: 'Facile', 2: 'Modéré', 3: 'Exigeant', 4: 'Expert' };
  const gcol = g => C(`--g${g}`);
  // terrain sections inside each outing (risque_sections.js, outils/segmentation_terrain.js)
  const EP = window.RISK_EPISODES || { episodes: [], persist: null };
  const SEC = window.RISK_SECTIONS || { seg_grade: R.series.map(s => rowOf(s.act).grade), sections: [] };
  const segG = i => SEC.seg_grade[i];
  const segKm = i => R.series[i].km - (i ? R.series[i - 1].km : 0);
  const CAS = { 1: 'T1', 2: 'T2', 3: 'T2–T3', 4: 'T3–T4' };
  const secWhy = x => !x.why ? 'cote de la sortie' : x.why.k === 'plat' ? 'plat roulant, allure normale' : `même sentier que « ${actName(x.why.o)} »`;
  const secOf = i => SEC.sections.find(x => i >= x.i0 && i <= x.i1);
  // D+ of each 250 m piece, rescaled so that each outing sums to its measured D+
  const segDp = (() => {
    const raw = R.series.map((s, i) => i && R.series[i - 1].act === s.act ? Math.max(0, s.alt - R.series[i - 1].alt) : 0);
    const tot = d3.rollup(R.series.map((s, i) => [s.act, raw[i]]), v => d3.sum(v, d => d[1]), d => d[0]);
    return raw.map((v, i) => { const a = R.series[i].act, t = tot.get(a); return t ? v / t * rowOf(a).dplus : 0; });
  })();

  /* ---------- tooltip ---------- */
  const tip = $('tip');
  function showTip(ev, html) {
    tip.innerHTML = html; tip.hidden = false;
    const r = tip.getBoundingClientRect(), pad = 14;
    let x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + r.width > innerWidth - 8) x = ev.clientX - r.width - pad;
    if (y + r.height > innerHeight - 8) y = ev.clientY - r.height - pad;
    tip.style.left = `${Math.max(8, x)}px`; tip.style.top = `${Math.max(8, y)}px`;
  }
  const hideTip = () => { tip.hidden = true; };
  const row = (k, v) => `<div class="r">${k}<em>${v}</em></div>`;
  const hover = (sel, html) => sel.on('pointermove', (ev, d) => showTip(ev, html(d))).on('pointerleave', hideTip);
  const readout = (id, html) => { const e = $(id); if (e) e.innerHTML = html; };

  /* ---------- frame and chrome ---------- */
  function frame(id, m) {
    const el = $(id); el.innerHTML = '';
    const W = Math.max(280, el.clientWidth - 8), H = +el.dataset.h;
    const svg = d3.select(el).append('svg').attr('viewBox', `0 0 ${W} ${H}`).attr('height', H).attr('role', 'img');
    const g = svg.append('g').attr('transform', `translate(${m.l},${m.t})`);
    return { el, svg, g, W, H, m, w: W - m.l - m.r, h: H - m.t - m.b, narrow: W < 560 };
  }
  // value axis on the right, as on a trading screen; left variant for charts with a right margin in use
  const yGrid = (g, y, w, n = 5, fmt = f0, side = 'right') => {
    g.append('g').attr('class', 'gridl').call(d3.axisLeft(y).ticks(n).tickSize(-w).tickFormat('')).lower();
    if (side === 'right') g.append('g').attr('class', 'axis').attr('transform', `translate(${w},0)`).call(d3.axisRight(y).ticks(n).tickSize(0).tickPadding(8).tickFormat(fmt));
    else g.append('g').attr('class', 'axis').call(d3.axisLeft(y).ticks(n).tickSize(0).tickPadding(8).tickFormat(fmt));
  };
  const xAxis = (g, x, h, n, fmt) => g.append('g').attr('class', 'axis').attr('transform', `translate(0,${h})`)
    .call(d3.axisBottom(x).ticks(n).tickSize(0).tickPadding(9).tickFormat(fmt));
  const axTitle = (g, txt, x, y, anchor = 'start') => g.append('text').attr('class', 'ax-title').attr('x', x).attr('y', y).attr('text-anchor', anchor).text(txt);
  function barPath(x, y0, w, y1, rr = 2) {
    const up = y1 < y0, hgt = Math.abs(y1 - y0); const r = Math.min(rr, hgt, w / 2);
    if (hgt < .5) return '';
    return up
      ? `M${x},${y0}V${y1 + r}Q${x},${y1} ${x + r},${y1}H${x + w - r}Q${x + w},${y1} ${x + w},${y1 + r}V${y0}Z`
      : `M${x},${y0}V${y1 - r}Q${x},${y1} ${x + r},${y1}H${x + w - r}Q${x + w},${y1} ${x + w},${y1 - r}V${y0}Z`;
  }
  const warnTri = (g, x, y, s = 1) => {
    const t = g.append('g').attr('transform', `translate(${x},${y}) scale(${s})`);
    t.append('path').attr('d', 'M0,-7 7,5.5 -7,5.5Z').attr('fill', C('--warning')).attr('stroke', C('--bg')).attr('stroke-width', 1.5).attr('stroke-linejoin', 'round');
    t.append('rect').attr('x', -.9).attr('y', -3).attr('width', 1.8).attr('height', 4.6).attr('rx', .9).attr('fill', '#111418');
    t.append('circle').attr('cy', 3.4).attr('r', .95).attr('fill', '#111418');
    return t;
  };
  const clip = f => { const id = `cl${Math.random().toString(36).slice(2, 8)}`; f.svg.append('defs').append('clipPath').attr('id', id).append('rect').attr('width', f.w).attr('height', f.h); return f.g.append('g').attr('clip-path', `url(#${id})`); };
  const legend = (id, items) => {
    $(id).innerHTML = items.map(([kind, col, txt]) => `<span><i class="${kind}" style="${kind === 'ring' ? `border-color:${col}` : kind === 'dash' ? `border-top-color:${col || 'var(--text-primary)'}` : `background:${col}`}"></i>${txt}</span>`).join('');
  };
  // a value tag on an axis, for crosshairs (filled label like on a trading screen)
  function axTag(g, x, y, txt, anchor = 'start') {
    const t = g.append('g').attr('class', 'axtag').style('pointer-events', 'none');
    const tx = t.append('text').attr('x', x + (anchor === 'start' ? 5 : anchor === 'end' ? -5 : 0)).attr('y', y).attr('dy', '.35em').attr('text-anchor', anchor).text(txt);
    const b = tx.node().getBBox();
    const wd = Math.max(b.width + 8, 46), x0 = anchor === 'middle' ? b.x + b.width / 2 - wd / 2 : anchor === 'end' ? b.x + b.width + 4 - wd : b.x - 4;
    t.insert('rect', 'text').attr('x', x0).attr('y', b.y - 2).attr('width', wd).attr('height', b.height + 4).attr('rx', 3);
    return t;
  }
  function crossH(f) {   // a horizontal + vertical crosshair pair, hidden until used
    const gx = f.g.append('g').style('display', 'none').style('pointer-events', 'none');
    const v = gx.append('line').attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '3 3');
    const h = gx.append('line').attr('x1', 0).attr('x2', f.w).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '3 3');
    let tags = [];
    return {
      show(px, py, yTxt, xTxt) {
        gx.style('display', null); v.attr('x1', px).attr('x2', px);
        if (py == null) h.style('display', 'none'); else h.style('display', null).attr('y1', py).attr('y2', py);
        tags.forEach(t => t.remove()); tags = [];
        if (py != null && yTxt) tags.push(axTag(gx, f.w + 2, py, yTxt));
        if (xTxt) tags.push(axTag(gx, px, f.h + 12, xTxt, 'middle'));
      },
      hide() { gx.style('display', 'none'); },
    };
  }
  // day separators along a km axis, labelled at the top (session breaks)
  function dayBands(g, x, h, top = true) {
    R.day_bounds.forEach((d, i) => {
      if (i) g.append('line').attr('class', 'daysep').attr('x1', x(d.km)).attr('x2', x(d.km)).attr('y1', 0).attr('y2', h);
      const end = i < R.day_bounds.length - 1 ? R.day_bounds[i + 1].km : R.series[R.series.length - 1].km;
      if (top) g.append('text').attr('class', 'lbl').attr('x', (x(d.km) + x(end)) / 2).attr('y', -6).attr('text-anchor', 'middle').text(dayLbl(d.day));
    });
  }

  /* ---------- header: ticker, scope, KPIs ---------- */
  const D = window.RISK_DIST || R.dist, MC = R.mc, W_ = R.weather;
  // rolling pace and irregularity recomputed without the GPS artefact (outils/distribution.js)
  if (D.roll_sd) { R.series.forEach((s, i) => { s.m = D.roll_m[i]; s.sd = D.roll_sd[i]; }); R.reg_thr = D.roll_p90; R.long_sd = D.roll_mean_sd; }
  // danger index recomputed without the GPS artefact (outils/indice_danger.js)
  const IX = window.RISK_INDICE;
  if (IX) { IX.rows.forEach(o => Object.assign(R.rows.find(r => r.id === o.id), o)); R.idx = IX.idx; }
  const sens = Object.fromEntries(R.sens.map(s => [s.name, s]));
  const sacS = sens['sac sur le dos'];
  const physIds = ['stuvla', 'last_trail', 'bunes_munkebu', 'andstabben'];
  const physRanks = physIds.map(id => rowOf(id).rank).sort((a, b) => a - b);
  const tailRatio = D.beyond3 / D.norm3;
  const j3 = MC.days.indexOf(3);
  const pN = MC.normal.p_over10[j3], pB = MC.blocs.p_over10[j3];
  const NS_ = MC.normal.seg, BS_ = MC.blocs.seg;
  const lateRain = d3.sum(W_.days.filter(d => d.day >= 7), d => d.rain);
  const worstN = R.nights.reduce((a, b) => b.hrv < a.hrv ? b : a), HRV_USUAL = 45;
  const totKm = d3.sum(R.rows, r => r.km), totDp = d3.sum(R.rows, r => r.dplus);
  $('ticker').innerHTML = [
    ['Tronçons', f0(D.n), ''], ['σ écart', f2(D.sd), ''], ['Kurtosis', fs2(D.kurt), 'up'],
    ['P(|z| > 3)', `${f2(D.beyond3 * 100)} %`, `×${f1(tailRatio)}`], ['ρ₁ autocorr.', f2(R.acf_r[0]), ''],
    ['Pluie J7–J9', `${f1(lateRain)} mm`, `${fs0((W_.total_rain / W_.climato.pluie_mm - 1) * 100)} %`], ['VFC min', `${fs0((worstN.hrv / HRV_USUAL - 1) * 100)} %`, ''],
    ['σ arrivée MC', hm(BS_.term_sd), `${fs0((BS_.term_sd / NS_.term_sd - 1) * 100)} %`],
  ].map(([k, v, e]) => `<div><span>${k}</span><b>${v}</b>${e && e !== 'up' ? `<em class="up">${e}</em>` : ''}</div>`).join('');
  $('scope').innerHTML = [['Distance', `${f1(totKm)} km`], ['Dénivelé positif', `${f0(totDp)} m`], ['Jours de marche', '9'], ['Sorties', R.rows.length], ['Tronçons de 250 m', D.n], ['Nuits suivies', R.nights.length]]
    .map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('');
  $('kpis').innerHTML = [
    ['Persistance', `×${f1(EP.topo.agg.massif / EP.topo.agg.seg)}`, 'd’incertitude sur le temps total : les écarts s’additionnent dans un massif', `± ${f0(EP.topo.agg.massif)} min contre ± ${f0(EP.topo.agg.seg)} min tronçon par tronçon`],
    ['Effet du sac', `${fs0(sacS.pct)} %`, 'de temps par tronçon, à pente et terrain égaux', `IC 95 % : ${fs0(sacS.lo)} à ${fs0(sacS.hi)} %`],
    ['Indice de danger', `${physRanks.filter(r => r <= R.rows.length / 3).length} / ${physIds.length}`, 'alertes de terrain dans le tiers le plus exposé', `rangs ${physRanks.join(', ')} sur ${R.rows.length}`],
    ['Monte Carlo', `×${f0(pB / pN)}`, 'risque sous-estimé d’une journée de plus de 10 h par la loi normale', `J3 : ${f1(pB)} % contre ${f1(pN)} %`],
  ].map(([l, b, s, sm]) => `<div class="kpi"><span class="kl">${l}</span><b>${b}</b><span class="kd">${s}</span><small>${sm}</small></div>`).join('');
  if ($('n-seg')) $('n-seg').textContent = D.n;

  /* ---------- 01 · OHLC candles + D+ ---------- */
  function drawCandles() {
    const days = R.candles;
    // une bougie par sortie (risque_bougies.js, altitudes de tous les points GPS)
    const data = window.RISK_BOUGIES.map(d => ({ ...d }));
    const m = { t: 22, r: 58, b: 26, l: 8 };
    const f = frame('c-candles', m);
    const gap = .7, nd = new Set(data.map(d => d.day)).size, units = data.length + (nd - 1) * gap;
    const step = Math.min(f.w / units, 34), gw = step * units, off = (f.w - gw) / 2;
    let di = -1, prev = null;
    data.forEach((d, i) => { if (d.day !== prev) { di++; prev = d.day; } d.x = off + (i + di * gap + .5) * step; });
    const y = d3.scaleLinear().domain([0, d3.max(data, d => d.h) * 1.12]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${f0(v)} m`);
    const bw = Math.max(4, Math.min(step * .62, 18)), up = d => d.c >= d.o, col = d => up(d) ? C('--up') : C('--down');
    const groups = d3.groups(data, d => d.day);
    const sep = (g, h) => groups.slice(1).forEach(([, a]) => g.append('line').attr('class', 'daysep').attr('x1', a[0].x - step * (.5 + gap / 2)).attr('x2', a[0].x - step * (.5 + gap / 2)).attr('y1', 0).attr('y2', h));
    sep(f.g, f.h);
    groups.forEach(([day, a]) => f.g.append('text').attr('class', 'lbl').attr('x', (a[0].x + a[a.length - 1].x) / 2).attr('y', f.h + 17).attr('text-anchor', 'middle').text(dayLbl(day)));
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', f.h).attr('y2', f.h).attr('stroke', C('--border')).attr('stroke-width', 1);
    const cg = f.g.selectAll('.cd').data(data).join('g').attr('transform', d => `translate(${d.x},0)`);
    cg.append('line').attr('y1', d => y(d.h)).attr('y2', d => y(d.l)).attr('stroke', col).attr('stroke-width', 1).attr('shape-rendering', 'crispEdges');
    cg.append('rect').attr('x', -bw / 2).attr('width', bw)
      .attr('y', d => y(Math.max(d.o, d.c))).attr('height', d => Math.max(1.5, Math.abs(y(d.o) - y(d.c))))
      .attr('fill', col).attr('stroke', col).attr('stroke-width', 1).attr('shape-rendering', 'crispEdges');
    const top = data.reduce((a, b) => b.h > a.h ? b : a);
    const ro = d => `<b>${dayLbl(d.day)}</b> ${d.name}  O <b>${f0(d.o)}</b>  H <b>${f0(d.h)}</b>  B <b>${f0(d.l)}</b>  C <b class="${up(d) ? 'u' : 'd'}">${f0(d.c)}</b>  D+ <b>${f0(d.dplus)}</b>`;
    const def = `${data.length} sorties · H max <b>${f0(top.h)} m</b> (${top.name}) · D+ total <b>${f0(d3.sum(data, d => d.dplus))} m</b>`;
    readout('r-candles', def);
    const ch = crossH(f);
    const near = mx => data[d3.minIndex(data, d => Math.abs(d.x - mx))];
    const tip = (ev, d) => showTip(ev, `<b>${d.name} · ${dayLbl(d.day)}</b>${row('départ', `${f0(d.o)} m`)}${row('point haut', `${f0(d.h)} m`)}${row('point bas', `${f0(d.l)} m`)}${row('arrivée', `${f0(d.c)} m`)}${row('distance', `${f1(d.km)} km`)}${row('D+', `${f0(d.dplus)} m`)}${row('sac', d.sac ? 'avec' : 'sans (trail)')}${row('départ à', d.start)}${row('en mouvement', hm(d.mov_h))}`);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => { const [mx, my] = d3.pointer(ev), d = near(mx); ch.show(d.x, my, `${f0(y.invert(my))} m`); readout('r-candles', ro(d)); tip(ev, d); })
      .on('pointerleave', () => { ch.hide(); hideTip(); readout('r-candles', def); });

    const v = frame('c-volume', { t: 6, r: 58, b: 6, l: 8 });
    const yv = d3.scaleLinear().domain([0, d3.max(data, d => d.dplus)]).nice().range([v.h, 0]);
    yGrid(v.g, yv, v.w, 2, v_ => f0(v_));
    sep(v.g, v.h);
    v.g.selectAll('.vb').data(data).join('path').attr('transform', d => `translate(${d.x - bw / 2},0)`)
      .attr('d', d => barPath(0, yv(0), bw, yv(d.dplus), 0)).attr('fill', col).attr('fill-opacity', d => d.sac ? .35 : .8);
    legend('l-candles', [['', C('--up'), 'arrivée plus haute'], ['', C('--down'), 'arrivée plus basse'], ['', `color-mix(in srgb, ${C('--text-secondary')} 80%, transparent)`, 'D+ sans sac (plein) / avec sac (clair)']]);
    const big = days.reduce((a, b) => b.dplus > a.dplus ? b : a);
    const sansShare = d3.sum(days, d => d.dplus - d.dplus_sac) / d3.sum(days, d => d.dplus);
    $('t-candles').innerHTML = `<b>${f0(sansShare * 100)} %</b> du D+ monté sans le sac. <b>${dayLbl(big.day)}</b>, la journée la plus chargée (${f0(big.dplus)} m). <b>J8</b> : le campement n’a pas bougé, d’où la bougie plate.<br><br>Ce relief n’est pas qu’un décor : avec ou sans sac, en traversée ou en sommet, chaque sortie expose à un risque différent. Reste à voir comment ce dénivelé et ce profil ont pesé sur la prise de risque, et où le risque s’est réellement concentré. Première étape : qualifier le terrain.`;
  }

  /* ---------- 02 · terrain grading ---------- */
  const isEst = r => /critères/.test(r.src) && !/68north|Horizon|Hunting/.test(r.src);
  const srcL = r => isEst(r) ? 'DNT' : r.src;
  function drawTerrain() {
    const S = R.series, maxKm = S[S.length - 1].km;
    const m = { t: 22, r: 58, b: 30, l: 8 };
    const f = frame('c-terrain', m);
    const x = d3.scaleLinear().domain([0, maxKm]).range([0, f.w]);
    const y = d3.scaleLinear().domain([0, d3.max(S, s => s.alt) * 1.1]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 4, v => `${f0(v)} m`);
    xAxis(f.g, x, f.h, f.narrow ? 4 : 8, v => `${v} km`);
    dayBands(f.g, x, f.h);
    // one area per terrain section (a whole outing, or a flat / already-walked part of it)
    const runs = []; let cur = null;
    S.forEach((s, i) => { const g = segG(i); if (!cur || cur.act !== s.act || cur.g !== g) { if (cur) cur.pts.push(s); cur = { act: s.act, pts: [], g }; runs.push(cur); } cur.pts.push(s); });
    const area = d3.area().x(s => x(s.km)).y0(f.h).y1(s => y(s.alt)).curve(d3.curveMonotoneX);
    const ln = d3.line().x(s => x(s.km)).y(s => y(s.alt)).curve(d3.curveMonotoneX);
    runs.forEach(r => {
      f.g.append('path').attr('d', area(r.pts)).attr('fill', gcol(r.g)).attr('fill-opacity', r.g === 4 ? .85 : .42);
      f.g.append('path').attr('d', ln(r.pts)).attr('fill', 'none').attr('stroke', r.g === 4 ? C('--text-primary') : gcol(r.g)).attr('stroke-width', 1.4);
    });
    R.alerts.forEach(a => warnTri(f.g, x(a.km), y(R.series[a.seg].alt) - 12, .9));
    const ch = crossH(f);
    const segTot = d3.sum(S, (_, i) => segKm(i));
    const share = g => d3.sum(S, (_, i) => segG(i) >= g ? segKm(i) : 0) / segTot;
    const def = `exigeant + expert : <b>${f0(share(3) * 100)} %</b> de la distance · expert : <b>${f0((share(4)) * 100)} %</b>`;
    readout('r-terrain', def);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => {
        const [mx] = d3.pointer(ev); const si = d3.minIndex(S, q => Math.abs(q.km - x.invert(mx))), s = S[si], r = rowOf(s.act), g = segG(si), sec = secOf(si);
        ch.show(x(s.km), y(s.alt), `${f0(s.alt)} m`, `${f1(s.km)} km`);
        readout('r-terrain', `<b>${dayLbl(s.day)}</b> ${r.name} · <b>${GL[g]}</b>${g === r.grade ? ` · ${r.sac_t}` : ` · passage clé ${GL[r.grade]}`}`);
        showTip(ev, `<b>${r.name} · ${dayLbl(s.day)}</b>${row('cote ici', GL[g])}${sec ? row('section', `${f1(sec.i0 ? S[sec.i0 - 1].km : 0)} → ${f1(S[sec.i1].km)} km`) : ''}${row('pourquoi', sec ? secWhy(sec) : 'cote de la sortie')}${row('passage clé', `${GL[r.grade]} · ${r.sac_t}`)}${row('altitude', `${f0(s.alt)} m`)}${row('pente du tronçon', `${s.slope} %`)}${row('source', srcL(r))}`);
      }).on('pointerleave', () => { ch.hide(); hideTip(); readout('r-terrain', def); });
    legend('l-terrain', [1, 2, 3, 4].map(g => ['', g === 4 ? `${gcol(4)};box-shadow:inset 0 0 0 1px var(--text-muted)` : gcol(g), GL[g]]).concat([['', C('--warning'), 'alerte']]));

    // distance mix
    const mix = [1, 2, 3, 4].map(g => ({ g, km: d3.sum(S, (_, i) => segG(i) === g ? segKm(i) : 0) / segTot * totKm, n: SEC.sections.filter(x => x.g === g).length, dp: d3.sum(S, (_, i) => segG(i) === g ? segDp[i] : 0) }));
    $('grade-mix').innerHTML = `<div class="gm-bar">${mix.map(d => `<i style="flex:${d.km};background:${gcol(d.g)}${d.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}" title="${GL[d.g]}"></i>`).join('')}</div>
      <div class="gm-rows">${mix.map(d => `<div class="gm-row"><i style="background:${gcol(d.g)}${d.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}"></i><span>${GL[d.g]} <span class="mono">· ${d.n} sections</span></span><span class="mono">${f1(d.km)} km · ${f0(d.dp)} m D+</span><span class="mono"><b>${f0(d.km / totKm * 100)} %</b></span></div>`).join('')}</div>`;
    $('grade-legend').innerHTML = [
      [1, 'T1', 'Sentier facile, sans passage raide ni obstacle.'],
      [2, 'T2', 'Montées modérées, quelques passages plus raides.'],
      [3, 'T2–T3', 'Terrain rocheux ou étroit, pierriers, mains parfois utiles.'],
      [4, 'T3–T4', 'Arêtes, roche nue, passages exposés à franchir avec les mains.'],
    ].map(([g, t, d]) => `<div><span class="chipg l${g}"><i></i>${GL[g]}</span><span class="mono">${t}</span><span>${d}</span></div>`).join('');
    const rows = [...R.rows].sort((a, b) => a.day - b.day || 0);
    const split = r => { const ss = SEC.sections.filter(x => x.act === r.id), k = x => d3.sum(d3.range(x.i0, x.i1 + 1), segKm), tot = d3.sum(ss, k);
      return `<span class="secbar" title="${ss.map(x => `${GL[x.g]} ${f1(k(x) / tot * r.km)} km (${secWhy(x)})`).join(' · ')}">${ss.map(x => `<i style="flex:${k(x)};background:${gcol(x.g)}${x.g === 4 ? ';box-shadow:inset 0 0 0 1px var(--text-muted)' : ''}"></i>`).join('')}</span>`; };
    $('terrain-table').innerHTML = `<thead><tr><th>Jour</th><th>Sortie</th><th>Passage clé</th><th>CAS</th><th>Découpage</th><th class="n">km</th><th class="n">D+</th><th class="n">Pente raide</th><th>Source</th></tr></thead><tbody>${rows.map(r => `<tr><td class="nw mono">${dayLbl(r.day)}</td><td>${r.name}</td><td><span class="chipg l${r.grade}"><i></i>${GL[r.grade]}</span></td><td class="mono">${r.sac_t}</td><td>${split(r)}</td><td class="n">${f1(r.km)}</td><td class="n">${f0(r.dplus)}</td><td class="n">${f0(r.pente_max)} %</td><td class="muted">${srcL(r)}</td></tr>`).join('')}</tbody>`;
    const alG = R.alerts.map(a => segG(a.seg));
    $('t-terrain').innerHTML = `<b>${f0(share(3) * 100)} %</b> de la distance en terrain exigeant ou expert. Chaque niveau de cote ajoute <b>${fs0(sens['terrain (+1 niveau)'].pct)} %</b> au temps de passage.<br><br>La traversée est maintenant découpée et cotée sérieusement : on peut analyser la prise de risque en profondeur. Cette cotation est déjà une analyse de risque en soi : elle combine des facteurs quantitatifs et déterministes (pente, D+, longueur, exposition) et l’évaluation officielle de guides qui connaissent le terrain.`;
  }

  /* ---------- 03 · distribution ---------- */
  function drawDist() {
    const m = { t: 16, r: 46, b: 34, l: 8 };
    const f = frame('c-hist', m);
    const x = d3.scaleLinear().domain([D.edges[0], D.edges[D.edges.length - 1]]).range([0, f.w]);
    const bins = D.hist.map((n, i) => ({ n, a: D.edges[i], b: D.edges[i + 1] }));
    const y = d3.scaleLinear().domain([0, d3.max([d3.max(D.hist), d3.max(D.pdf_t)]) * 1.1]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 4);
    xAxis(f.g, x, f.h, 8, F('+.1f'));
    axTitle(f.g, 'écart e (0 = dans mon allure)', 0, f.h + 30);
    const z = v => Math.abs((v - D.mu) / D.sd) > 2;
    f.g.selectAll('.hb').data(bins).join('path')
      .attr('d', d => barPath(x(d.a) + .5, y(0), Math.max(1, x(d.b) - x(d.a) - 1.5), y(d.n), 1))
      .attr('fill', d => z((d.a + d.b) / 2) ? C('--down') : C('--accent')).attr('fill-opacity', d => z((d.a + d.b) / 2) ? .9 : .45);
    [-2, 2].forEach(k => {
      const xv = x(D.mu + k * D.sd);
      f.g.append('line').attr('x1', xv).attr('x2', xv).attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '2 3');
      f.g.append('text').attr('class', 'lbl tagt').attr('x', xv + 4).attr('y', 10).text(`${k > 0 ? '+' : '−'}2σ`);
    });
    const ln = d3.line().x((d, i) => x(D.xs[i])).y(d => y(d)).curve(d3.curveBasis);
    f.g.append('path').attr('d', ln(D.pdf)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.6).attr('stroke-dasharray', '5 4');
    f.g.append('path').attr('d', ln(D.pdf_t)).attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.4).attr('opacity', .8);
    hover(f.g.selectAll('.hh').data(bins).join('rect').attr('class', 'hit').attr('x', d => x(d.a)).attr('width', d => x(d.b) - x(d.a)).attr('y', 0).attr('height', f.h),
      d => { const mid = (d.a + d.b) / 2, i = d3.minIndex(D.xs, v => Math.abs(v - mid)); return `<b>e entre ${f2(d.a)} et ${f2(d.b)}</b>${row('temps réel / attendu', `×${f2(Math.exp(d.a))} à ×${f2(Math.exp(d.b))}`)}${row('tronçons observés', d.n)}${row('attendus si loi normale', f1(D.pdf[i]))}`; });
    legend('l-hist', [['', C('--accent'), 'tronçons'], ['', C('--down'), 'au-delà de ±2σ'], ['dash', '', 'loi normale'], ['ln', C('--warning'), 'loi de Student ajustée']]);
    readout('r-hist', `${f0(D.n)} tronçons · σ <b>${f2(D.sd)}</b>`);

    // indicators, each one explained on the walk itself, with a verdict
    const SS = R.series, okI = SS.map((q, i) => i).filter(i => Math.abs(SS[i].slope) <= 60);
    const base = Math.round(d3.median(okI, i => EP.seg_t[i] * Math.exp(-SS[i].e) / 60) * 2) / 2;   // typical expected time of a piece
    const mn = v => { const t = Math.round(v * 60); return `${Math.floor(t / 60)} min ${String(t % 60).padStart(2, '0')}`; };
    const cnt = f => okI.filter(i => f(SS[i].e)).length, l2 = Math.log(2);
    const nSlow2 = cnt(v => v > l2), nFast2 = cnt(v => v < -l2);
    const Phi_ = x => { const t = 1 / (1 + .3275911 * Math.abs(x) / Math.SQRT2), y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - .284496736) * t + .254829592) * t * Math.exp(-x * x / 2); return .5 * (1 + (x >= 0 ? y : -y)); };
    const exp2 = D.n * (1 - Phi_((l2 - D.mu) / D.sd));
    const ex3 = (D.extremes || []).map(e => ({ ...e, t: EP.seg_t[e.i] / 60, x: EP.seg_t[e.i] * Math.exp(-SS[e.i].e) / 60 }));
    const NM = { bunes_munkebu: 'le sentier fantôme', reinebringen_helvete: 'l’arête de Reinebringen', stuvla: 'la barre du Støvla', ryten: 'la descente du Ryten' };
    const ex3txt = [...ex3].sort((a, b) => b.z - a.z).map(e => e.act === 'stuvla' || e.act === 'ryten' ? `${NM[e.act] || actName(e.act)} (prévu ${mn(e.x)}, fait en ${mn(e.t)})` : (NM[e.act] || actName(e.act))).join(', ');
    const t3 = D.tails.find(d => d.k === 3), allJB = R.dist;
    const V = { ok: ['c-ok', 'normal'], warn: ['c-sub', 'à surveiller'], info: ['c-av', 'repère'] };
    const rows = [
      ['Écart-type σ', 'La largeur de la cloche : de combien on s’écarte d’habitude.',
        `<b>${f2(D.sd)}</b>. Sur un tronçon prévu en ${mn(base)}, deux fois sur trois je mets entre ${mn(base * Math.exp(-D.sd))} et ${mn(base * Math.exp(D.sd))}.`, 'info'],
      ['Asymétrie', 'Les deux côtés sont-ils pareils ? Positive si les lents s’éloignent plus que les rapides.',
        `<b>${fs2(D.skew)}</b>. ${nSlow2} tronçons deux fois plus lents que prévu, ${nFast2} deux fois plus rapides ; une loi normale en attend ${f0(exp2)} de chaque côté.`, Math.abs(D.skew) < .3 ? 'ok' : 'warn'],
      ['Kurtosis', 'L’épaisseur des queues : les très gros écarts sont-ils fréquents ? 0 pour une loi normale.',
        `<b>${fs2(D.kurt)}</b>. Seuls ${D.n3} tronçons sur ${f0(D.n)} sont trois fois plus lents ou plus rapides que prévu. Avec des queues épaisses, il y en aurait environ ${f0(t3.t4 * D.n)}.`, D.kurt < 1 ? 'ok' : 'warn'],
      ['Test de Jarque-Bera', 'Réunit asymétrie et kurtosis en un score : plus il est grand, moins la loi normale est crédible. Au-delà de 6, on la rejette.',
        `<b>${f1(D.jb)}</b>, un score qu’une vraie loi normale donne ${f0(D.jb_p * 100)} fois sur 100 par hasard : rien d’anormal. Avec l’erreur GPS de Kvalvika gardée, il montait à ${f0(allJB.n / 6 * (allJB.skew ** 2 + allJB.kurt ** 2 / 4))} : un seul tronçon faux faisait croire à des queues épaisses.`, D.jb_p > .05 ? 'ok' : 'warn'],
      ['Au-delà de 2σ', 'Les écarts marqués.',
        `<b>${D.n2} tronçons</b> au moins ${f1(Math.exp(2 * D.sd))} fois plus lents ou deux fois plus rapides ; une loi normale en attend ${f0(D.n * D.norm2)}. Ce sont surtout les passages techniques et les descentes courues (partie 04).`, 'ok'],
      ['Au-delà de 3σ', 'Les vraies surprises.',
        `<b>${D.n3} tronçons</b> : ${ex3txt}. Une loi normale en attend ${f1(D.exp3)} : léger excès, qu’on obtiendrait par hasard ${f0(D.p_pois3 * 100)} fois sur 100.`, 'warn'],
      ['Loi de Student', 'Une cloche à queues réglables (outil 2). Peu de degrés de liberté, queues épaisses ; beaucoup, loi normale.',
        `<b>${f0(D.t_df)} degrés</b> une fois ajustée sur mes tronçons : presque la normale. À 4 degrés, on aurait eu environ ${f0(t3.t4 * D.n)} tronçons au-delà de 3σ ; j’en ai ${D.n3}.`, D.t_df > 20 ? 'ok' : 'warn'],
      ['Avec ou sans sac', 'La même largeur, mesurée séparément.',
        `Sur un tronçon prévu en ${mn(base)} : avec le sac, entre ${mn(base * Math.exp(-D.sd_avec))} et ${mn(base * Math.exp(D.sd_avec))} ; en trail, entre ${mn(base * Math.exp(-D.sd_sans))} et ${mn(base * Math.exp(D.sd_sans))}. Sans le sac, on pousse, on court, on s’arrête.`, 'info'],
    ];
    $('dist-stats').innerHTML = `<thead><tr><th>Indicateur</th><th>Ce que ça mesure</th><th>Sur ma traversée</th><th>Verdict</th></tr></thead><tbody>${rows.map(([a, m, t, k]) => `<tr><td><b>${a}</b></td><td class="muted">${m}</td><td>${t}</td><td><span class="chip ${V[k][0]}">${V[k][1]}</span></td></tr>`).join('')}</tbody>`;
    readout('r-dstats', D.jb_p > .05 ? 'normalité <b>non rejetée</b>' : 'normalité <b>rejetée</b>');

    const q = frame('c-qq', { t: 14, r: 46, b: 32, l: 8 });
    const ext = d3.extent(D.qq.flat()), lim = [Math.floor(ext[0] - .2), Math.ceil(ext[1] + .2)];
    const xq = d3.scaleLinear().domain(lim).range([0, q.w]), yq = d3.scaleLinear().domain(lim).range([q.h, 0]);
    yGrid(q.g, yq, q.w, 6, F('+d'));
    xAxis(q.g, xq, q.h, 8, F('+d'));
    axTitle(q.g, 'position attendue si loi normale (en σ)', 0, q.h + 28);
    [[lim[0], -3], [3, lim[1]]].forEach(([a, b]) => q.g.append('rect').attr('x', xq(a)).attr('width', xq(b) - xq(a)).attr('y', 0).attr('height', q.h).attr('fill', C('--down')).attr('opacity', .06));
    q.g.append('line').attr('x1', xq(lim[0])).attr('y1', yq(lim[0])).attr('x2', xq(lim[1])).attr('y2', yq(lim[1])).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2).attr('stroke-dasharray', '5 4');
    q.g.selectAll('.qd').data(D.qq).join('circle').attr('cx', d => xq(d[0])).attr('cy', d => yq(d[1])).attr('r', 2.6)
      .attr('fill', d => Math.abs(d[1]) > 3 ? C('--down') : C('--accent')).attr('fill-opacity', d => Math.abs(d[1]) > 3 ? 1 : .7);
    // name the extremes
    const LBL = { bunes_munkebu: 'le sentier fantôme vers Munkebu', reinebringen_helvete: 'l’arête de Reinebringen', stuvla: 'la barre du Støvla', ryten: 'la descente du Ryten' };
    const nm = e => LBL[e.act] || actName(e.act);
    const ex = (D.extremes || []).map(e => ({ ...e, q: D.qq.find(p => Math.abs(p[1] - e.z) < .002) })).filter(e => e.q);
    // labels stacked so they never overlap: slow ones down the left of their point, fast ones to the right
    const hiEx = ex.filter(e => e.z > 0).sort((a, b) => b.z - a.z), loEx = ex.filter(e => e.z < 0);
    hiEx.forEach((e, k) => { const ty = yq(e.q[1]) + k * 15 + 4, tx = xq(e.q[0]) - 34;
      q.g.append('line').attr('x1', tx + 3).attr('y1', ty - 4).attr('x2', xq(e.q[0]) - 3).attr('y2', yq(e.q[1])).attr('stroke', C('--text-muted')).attr('stroke-width', .8);
      q.g.append('text').attr('class', 'lbl-strong').attr('x', tx).attr('y', ty).attr('text-anchor', 'end').text(`${nm(e)} · ${dayLbl(e.day)}`); });
    loEx.forEach(e => q.g.append('text').attr('class', 'lbl-strong').attr('x', xq(e.q[0]) + 8).attr('y', yq(e.q[1]) + 4).text(`${nm(e)} · ${dayLbl(e.day)}`));
    q.g.append('text').attr('class', 'ax-title').attr('x', 4).attr('y', 10).text('écart observé (en σ)');
    hover(q.g.selectAll('.qh').data(D.qq).join('circle').attr('class', 'hit').attr('cx', d => xq(d[0])).attr('cy', d => yq(d[1])).attr('r', 8),
      d => `<b>écart observé ${fs2(d[1])} σ</b>${row('attendu si loi normale', `${fs2(d[0])} σ`)}`);
    readout('r-qq', `${D.n3} tronçons au-delà de 3σ`);

    const art = (D.artefacts || [])[0];
    $('n-dist-read').textContent = 'Si les écarts sont ordinaires, les barres suivent la courbe en pointillés et les points restent sur la diagonale. Seuls les points tout au bout s’en écartent ici.';
    $('n-dist-meth').textContent = `${f0(D.n)} tronçons de 250 m.${art ? ` Un tronçon retiré : ${actName(art.act)}, pente GPS de ${f0(art.slope)} %, altitude erronée.` : ''} Loi normale ajustée par la moyenne et l’écart-type, loi de Student par maximum de vraisemblance.`;
    const slow = ex.filter(e => e.z > 0).map(nm), fast = ex.filter(e => e.z < 0).map(nm);
    $('t-dist').innerHTML = `Pris un par un, les tronçons sont <b>ordinaires</b> : la loi normale les décrit bien (Jarque-Bera p = ${f2(D.jb_p)}). Seuls <b>${D.n3}</b> s’en échappent : ${slow.join(', ')} en lent, ${fast.join(', ')} en rapide.<br><br>Le danger ne vient donc pas d’un pas isolé. La partie 04 regarde ces quelques extrêmes, puis la suite montre où le risque se construit vraiment : dans l’enchaînement.`;
  }

  /* ---------- 03 · the three tools: Tobler, Student, maximum likelihood ---------- */
  function drawTools() {
    const S = R.series, mm = D.mode_mu || R.dist.mode_mu, tob = sl => 6 * Math.exp(-3.5 * Math.abs(sl / 100 + .05));
    {
      const f = frame('c-tobler', { t: 8, r: 40, b: 26, l: 6 });
      const x = d3.scaleLinear().domain([-40, 40]).range([0, f.w]), y = d3.scaleLinear().domain([0, 7]).range([f.h, 0]);
      yGrid(f.g, y, f.w, 3, v => `${v} km/h`);
      xAxis(f.g, x, f.h, 4, v => `${v > 0 ? '+' : ''}${v} %`);
      const xs = d3.range(-40, 40.5, .5), ln = k => d3.line().x(v => x(v)).y(v => y(tob(v) * k))(xs);
      f.g.append('path').attr('d', ln(1)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.4).attr('stroke-dasharray', '4 3');
      f.g.append('path').attr('d', ln(Math.exp(-mm.avec))).attr('fill', 'none').attr('stroke', C('--series-avec')).attr('stroke-width', 1.8);
      f.g.append('path').attr('d', ln(Math.exp(-mm.sans))).attr('fill', 'none').attr('stroke', C('--series-sans')).attr('stroke-width', 1.8).attr('opacity', .8);
      // my real speed: median per 5 % slope class
      const pts = [];
      [1, 0].forEach(sac => d3.range(-35, 36, 5).forEach(c => {
        const v = S.map((s, i) => [s, i]).filter(([s]) => s.sac === sac && Math.abs(s.slope) <= 60 && s.slope >= c - 2.5 && s.slope < c + 2.5)
          .map(([s, i]) => (s.km - (i ? S[i - 1].km : 0)) / (EP.seg_t[i] / 3600)).filter(v => isFinite(v) && v > 0);
        if (v.length >= 5) pts.push({ sac, c, v: d3.median(v), n: v.length });
      }));
      hover(f.g.selectAll(null).data(pts).join('circle').attr('cx', d => x(d.c)).attr('cy', d => y(Math.min(7, d.v))).attr('r', 3)
        .attr('fill', d => d.sac ? C('--series-avec') : C('--series-sans')).attr('stroke', C('--bg')),
        d => `<b>pente ${d.c > 0 ? '+' : ''}${d.c} % · ${d.sac ? 'avec sac' : 'trail'}</b>${row('ma vitesse (médiane)', `${f1(d.v)} km/h`)}${row('Tobler', `${f1(tob(d.c))} km/h`)}${row('tronçons', d.n)}`);
    }
    {
      const T = D.tails, f = frame('c-student', { t: 8, r: 40, b: 26, l: 6 });
      const x = d3.scaleLinear().domain([1, 3.5]).range([0, f.w]), y = d3.scaleLog().domain([.0004, .4]).range([f.h, 0]);
      yGrid(f.g, y, f.w, 3, v => `${F('.2~f')(v * 100)} %`);
      f.g.select('.axis').selectAll('.tick').filter(v => ![.001, .01, .1].some(k => Math.abs(v - k) < 1e-9)).remove();
      f.g.select('.gridl').selectAll('.tick').filter(v => ![.001, .01, .1].some(k => Math.abs(v - k) < 1e-9)).remove();
      xAxis(f.g, x, f.h, 5, v => `${v}σ`);
      const ln = k => d3.line().x(d => x(d.k)).y(d => y(Math.max(.0004, d[k]))).curve(d3.curveMonotoneX)(T);
      f.g.append('path').attr('d', ln('t4')).attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.6).attr('stroke-dasharray', '4 3');
      f.g.append('path').attr('d', ln('normal')).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.4);
      hover(f.g.selectAll(null).data(T.filter(d => d.obs > 0)).join('circle').attr('cx', d => x(d.k)).attr('cy', d => y(d.obs)).attr('r', 3.6).attr('fill', C('--accent')).attr('stroke', C('--bg')),
        d => `<b>écarts au-delà de ${f1(d.k)}σ</b>${row('mes tronçons', `${f2(d.obs * 100)} %`)}${row('loi normale', `${f2(d.normal * 100)} %`)}${row('Student, 4 ddl', `${f2(d.t4 * 100)} %`)}`);
    }
    const t3 = D.tails.find(d => d.k === 3), eUp = d3.mean(R.series.filter(s => s.slope > 15 && s.slope <= 60), s => s.e), eDn = d3.mean(R.series.filter(s => s.slope <= -5 && s.slope >= -15), s => s.e);
    const st = R.series[539], stT = EP.seg_t[539] / 60, stX = stT * Math.exp(-st.e), mn2 = v => { const t = Math.round(v * 60); return `${Math.floor(t / 60)} min ${String(t % 60).padStart(2, '0')}`; };
    $('x-tobler').innerHTML = `<b>Sert à :</b> fixer le temps attendu de chaque tronçon. Exemple : sur la barre du Støvla (${st.slope > 0 ? '+' : ''}${f0(st.slope)} %), le temps attendu était ${mn2(stX)} ; j’ai mis ${mn2(stT)}, soit e = ${fs2(st.e)}, ×${f1(Math.exp(st.e))}.<br>Waldo Tobler a résumé en 1993 la vitesse de marche selon la pente (pointillés) : <b>v = 6 · e<sup>−3,5 · |pente + 0,05|</sup> km/h</b>. Maximum en légère descente (6 km/h à −5 %), 5 km/h sur le plat, 2,5 km/h à +20 %. Recalée sur mon allure : <b>${f0((1 - Math.exp(-mm.avec)) * 100)} % moins vite</b> que Tobler avec le sac (bleu), à peu près sa vitesse en trail (orange). Les points sont ma vitesse réelle : ${f0((1 - Math.exp(eUp)) * 100)} % plus rapide que prévu dans les montées de plus de 15 %, ${f0((Math.exp(eDn) - 1) * 100)} % plus lente dans les descentes douces, où Tobler suppose qu’on court. Tobler ne connaît ni le terrain ni mon entraînement : c’est ce qui reste dans l’écart e.`;
    $('x-student').innerHTML = `<b>Sert à :</b> vérifier si les grosses surprises sont plus fréquentes que la loi normale ne le dit, ce qui obligerait à prévoir plus de marge.<br>Une cloche comme la loi normale, avec un réglage en plus : les <b>degrés de liberté</b>. Peu de degrés, et les queues s’épaississent : avec 4 (pointillés), un écart au-delà de 3σ arrive <b>${f0(t3.t4 / t3.normal)} fois</b> plus souvent qu’avec la loi normale (trait plein). Beaucoup, et elle redevient la normale. Les points sont mes tronçons : ils suivent la loi normale. Ajustée sur eux, la Student prend <b>${f0(D.t_df)} degrés</b>, presque une normale.`;
    $('c-ml').innerHTML = [['Loi normale', '2 réglages', 'centre, largeur'], ['Loi de Student', '3 réglages', '+ degrés de liberté'], ['Gain de la Student', `+${f1(D.ll_gain)}`, 'log-vraisemblance'], ['Bilan (critère d’Akaike)', Math.abs(D.d_aic) < 2 ? 'égalité' : D.d_aic < 0 ? 'Student' : 'normale', 'la plus simple l’emporte']]
      .map(([a, b, c], i) => `<div class="ml-row${i === 3 ? ' hl' : ''}"><span>${a} <span class="muted">· ${c}</span></span><b>${b}</b></div>`).join('');
    $('x-ml').innerHTML = `<b>Sert à :</b> régler la loi de Student sur mes tronçons, puis départager la Student et la normale.<br>Pour régler une loi, on essaie toutes les valeurs de ses réglages et on garde celles qui rendent les ${f0(D.n)} écarts observés <b>les plus probables</b> : c’est le maximum de vraisemblance. Pour départager deux lois, on compare cette probabilité en pénalisant chaque réglage en plus. Ici la Student ne gagne presque rien : <b>la loi normale suffit</b>.`;
  }

  /* ---------- 04 · tail table ---------- */
  function drawTail() {
    const T = D.tail, SS = R.series, LBL = { bunes_munkebu: 'sentier fantôme', reinebringen_helvete: 'arête, brouillard', stuvla: 'barre rocheuse', ryten: 'descente', volandstinden: 'descente', munkebu_reine: 'route de Reine' };
    // neighbouring pieces of the same outing form one passage (the Ryten descent is one descent, not four)
    const passages = list => {
      const P = []; [...list].sort((a, b) => a.i - b.i).forEach(t => { const last = P[P.length - 1];
        if (last && last.act === t.act && t.i - last.i1 <= 2) { last.i1 = t.i; last.items.push(t); } else P.push({ act: t.act, day: t.day, sac: t.sac, i0: t.i, i1: t.i, items: [t] }); });
      return P.map(p => { const ii = p.items.map(t => t.i), real = d3.sum(ii, i => EP.seg_t[i]), exp = d3.sum(ii, i => EP.seg_t[i] * Math.exp(-SS[i].e));
        const zz = p.items.reduce((b, t) => Math.abs(t.z) > Math.abs(b.z) ? t : b, p.items[0]);
        return { ...p, n: ii.length, km0: (p.i0 ? SS[p.i0 - 1].km : 0), km1: SS[p.i1].km, z: zz.z, mult: real / exp, grade: d3.max(p.items, t => t.grade), slope: d3.mean(p.items, t => t.slope) }; })
        .sort((a, b) => Math.abs(b.z) - Math.abs(a.z));
    };
    const PS = passages(T.slow), PF = passages(T.fast), slow = PS.slice(0, 3), fast = PF.slice(0, 3);
    const rowT = (t, k) => `<tr><td class="n">${k + 1}</td><td class="nw"><span class="dot" style="background:${t.sac ? C('--series-avec') : C('--series-sans')}" title="${t.sac ? 'avec le sac' : 'trail'}"></span>${actName(t.act).replace(/\s*\(.*\)$/, '')}<div class="muted">km ${t.n > 1 ? `${f1(t.km0)}–${f1(t.km1)}` : f1(t.km1)}${LBL[t.act] ? ` · ${LBL[t.act]}` : ''}</div></td><td class="mono">${dayLbl(t.day)}</td>
      <td><span class="chipg l${t.grade}"><i></i>${GL[t.grade]}</span></td><td class="n">${t.slope > 0 ? '+' : ''}${f0(t.slope)} %</td><td class="n">×${f1(t.mult)}</td>
      <td class="n">${fs2(t.z)}</td></tr>`;
    const head = '<colgroup><col style="width:7%"><col style="width:35%"><col style="width:8%"><col style="width:20%"><col style="width:10%"><col style="width:9%"><col style="width:11%"></colgroup><thead><tr><th class="n">#</th><th>Passage</th><th>Jour</th><th>Cote</th><th class="n">Pente</th><th class="n">Temps</th><th class="n">z</th></tr></thead>';
    $('tail-table').innerHTML = head + `<tbody>${slow.map(rowT).join('')}</tbody>`;
    $('tail-fast').innerHTML = head + `<tbody>${fast.map(rowT).join('')}</tbody>`;
    readout('r-tail', `${T.slow.length} tronçons au-delà de +2σ`); readout('r-tail-f', `${T.fast.length} tronçons au-delà de −2σ`);
    $('n-tail-meth').textContent = `Les ${f0(D.n)} tronçons de la partie 03, triés par z = (e − moyenne) / σ, avec σ = ${f2(D.sd)}. Les tronçons voisins d’une même sortie forment un passage ; z est celui du pire tronçon. Trois passages de chaque côté.`;
    const rep = d3.rollups([...T.slow, ...T.fast], v => v.length, t => t.act).filter(([, n]) => n >= 3).sort((a, b) => b[1] - a[1]);
    $('t-tail').innerHTML = `Lents : les passages du récit, en terrain exigeant ou expert. Rapides : des descentes courues en trail, et la route plate vers Reine.<br><br>Rares (${T.slow.length + T.fast.length} sur ${f0(D.n)}), ces extrêmes reviennent pourtant aux mêmes endroits : <b>${d3.sum(rep, r => r[1])} sur ${T.slow.length + T.fast.length}</b> dans ${rep.length} passages, de l’arête de Reinebringen à la descente du Ryten. Les écarts arrivent par passages entiers.`;
  }

  /* ---------- 05 · bands + rolling irregularity (shared crosshair) ---------- */
  const nearest = km => R.series[d3.minIndex(R.series, s => Math.abs(s.km - km))];
  function drawRoll() {
    const S = R.series, maxKm = S[S.length - 1].km, S2 = S.filter(s => s.sd != null);
    const EPS = EP.episodes.filter(d => d.sign < 0 || Math.round(d.lost_min) >= 5), pc = v => Math.exp(v) - 1, fpc = v => `${v >= 0 ? '+' : '−'}${f0(Math.abs(pc(v)) * 100)} %`;
    const epAt = i => EPS.find(x => i >= x.i0 && i <= x.i1);
    const m = { t: 22, r: 62, b: 6, l: 8 };
    const f = frame('c-bands', m);
    const x = d3.scaleLinear().domain([0, maxKm]).range([0, f.w]);
    const y = d3.scaleLinear().domain([-1.1, 1.3]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, fpc);
    dayBands(f.g, x, f.h);
    const cg = clip(f);
    const x0 = i => x(i ? S[i - 1].km : 0);
    // episodes as shaded bands behind the curves
    cg.selectAll('.ep').data(EPS).join('rect').attr('x', d => x0(d.i0)).attr('width', d => Math.max(1.5, x(S[d.i1].km) - x0(d.i0))).attr('y', 0).attr('height', f.h)
      .attr('fill', d => d.sign > 0 ? C('--down') : C('--up')).attr('opacity', d => d.gps ? .07 : .17);
    cg.append('line').attr('class', 'zero').attr('x1', 0).attr('x2', f.w).attr('y1', y(0)).attr('y2', y(0));
    const cl = v => Math.max(-1.1, Math.min(1.3, v));
    d3.groups(S, s => s.day).forEach(([, v]) => cg.append('path').attr('d', d3.line().x(s => x(s.km)).y(s => y(cl(s.e)))(v)).attr('fill', 'none').attr('stroke', C('--text-muted')).attr('stroke-width', .8).attr('opacity', .8));
    d3.groups(S2, s => s.day).forEach(([, v]) => cg.append('path').attr('d', d3.line().x(s => x(s.km)).y(s => y(cl(s.m))).curve(d3.curveMonotoneX)(v)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 1.8));
    // labels on the three costliest slow episodes
    const slow = EPS.filter(d => d.sign > 0).sort((a, b) => b.lost_min - a.lost_min);
    const MAJ = slow.filter(d => Math.round(d.lost_min) >= 10), PAU = slow.filter(d => Math.round(d.lost_min) < 10);
    slow.slice(0, f.narrow ? 2 : 4).forEach(d => {
      const cx = (x0(d.i0) + x(S[d.i1].km)) / 2;
      f.g.append('text').attr('class', 'lbl-strong').attr('x', cx).attr('y', y(1.3) + 12).attr('text-anchor', cx > f.w - 60 ? 'end' : 'middle').text(`${f0(d.lost_min)} min`);
    });

    const m2 = { t: 8, r: 62, b: 30, l: 8 };
    const g2 = frame('c-roll', m2);
    const x2 = x.copy().range([0, g2.w]);
    const y2 = d3.scaleLinear().domain([0, d3.max(S2, s => s.sd) * 1.08]).nice().range([g2.h, 0]);
    yGrid(g2.g, y2, g2.w, 3, F('.1f'));
    dayBands(g2.g, x2, g2.h, false);
    xAxis(g2.g, x2, g2.h, g2.narrow ? 4 : 8, v => `${v} km`);
    const thr = R.reg_thr;
    const idc = `rc${Math.random().toString(36).slice(2, 7)}`;
    g2.svg.append('defs').append('clipPath').attr('id', idc).append('rect').attr('width', g2.w).attr('height', y2(thr));
    d3.groups(S2, s => s.day).map(([, v]) => v).forEach(v => {
      const a = d3.area().x(s => x2(s.km)).y0(g2.h).y1(s => y2(s.sd)).curve(d3.curveMonotoneX)(v);
      g2.g.append('path').attr('d', a).attr('fill', C('--accent')).attr('opacity', .14);
      g2.g.append('path').attr('d', a).attr('fill', C('--down')).attr('opacity', .45).attr('clip-path', `url(#${idc})`);
      g2.g.append('path').attr('d', d3.line().x(s => x2(s.km)).y(s => y2(s.sd)).curve(d3.curveMonotoneX)(v)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 1.4);
    });
    g2.g.append('line').attr('x1', 0).attr('x2', g2.w).attr('y1', y2(thr)).attr('y2', y2(thr)).attr('stroke', C('--down')).attr('stroke-dasharray', '4 3');
    axTag(g2.g, g2.w + 2, y2(thr), `P90 ${f2(thr)}`).select('rect').attr('fill', C('--down'));
    R.alerts.forEach(a => { const t = warnTri(g2.g, x2(a.km), 8, .8); t.on('pointermove', ev => showTip(ev, `<b>${a.titre}</b>${row('km', f1(a.km))}${row('σ₂ₖₘ', a.sd == null ? '–' : f2(a.sd))}`)).on('pointerleave', hideTip); });
    const above = S2.filter(s => s.sd > thr).length;
    const def = `${slow.length} épisodes lents · <b>${f0(d3.sum(slow, d => d.lost_min))} min</b> perdues sur ${f0(d3.sum(slow, d => d.len))} km`;
    readout('r-roll', def);
    const c1 = crossH(f), c2 = crossH(g2);
    const move = (ev, xs) => {
      const s = nearest(xs.invert(d3.pointer(ev)[0])), i = S.indexOf(s), ep = epAt(i);
      c1.show(x(s.km), y(cl(s.e)), fpc(s.e)); c2.show(x2(s.km), s.sd == null ? null : y2(s.sd), s.sd == null ? '' : f2(s.sd), `${f1(s.km)} km`);
      readout('r-roll', `<b>${dayLbl(s.day)}</b> ${actName(s.act)} · tronçon <b>${fpc(s.e)}</b> · 2 km <b>${s.m == null ? '–' : fpc(s.m)}</b>${ep ? ` · épisode <b>${ep.lost_min > 0 ? '+' : '−'}${f0(Math.abs(ep.lost_min))} min</b>` : ''}`);
      if (ep) showTip(ev, `<b>${actName(ep.act)} · ${dayLbl(ep.day)}</b>${row('épisode', `km ${f1(ep.km0)} → ${f1(ep.km1)}`)}${row(ep.sign > 0 ? 'plus lent' : 'plus rapide', `${f0(Math.abs(ep.pct))} %`)}${row(ep.sign > 0 ? 'temps perdu' : 'temps gagné', `${f0(Math.abs(ep.lost_min))} min`)}${ep.gps ? row('attention', 'pente GPS douteuse') : ''}`); else hideTip();
    };
    const leave = () => { c1.hide(); c2.hide(); hideTip(); readout('r-roll', def); };
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h).on('pointermove', ev => move(ev, x)).on('pointerleave', leave);
    g2.g.append('rect').attr('class', 'hit').attr('y', 16).attr('width', g2.w).attr('height', g2.h - 16).on('pointermove', ev => move(ev, x2)).on('pointerleave', leave);
    legend('l-roll', [['ln', C('--text-muted'), 'tronçon'], ['ln', C('--accent'), 'moyenne glissante 2 km'], ['', C('--down'), 'épisode lent / irrégularité > P90'], ['', C('--up'), 'épisode rapide'], ['', C('--warning'), 'alerte']]);

    // table of the costly slow episodes (>= 10 min), with their causes
    const RS = window.RESSENTIS_EPISODES || {};
    const CAUSE = {
      sentier: ['Sentier peu visible', '--series-sans', 'Terrain subi'],
      terrain_instable: ['Terrain instable', '--critical', 'Terrain subi'],
      meteo: ['Météo', '--series-avec', 'Météo subie'],
      evaluation: ['Évaluation', '--accent', 'Arrêts et décisions'],
      arret: ['Arrêt', '--text-muted', 'Arrêts et décisions'],
      pause: ['Autre · pause probable', '--hair', 'Pauses probables'],
    };
    const chip = (k, main) => `<span class="cause${main ? '' : ' sec'}"><i style="background:${C(CAUSE[k][1])}"></i>${CAUSE[k][0]}</span>`;
    const majMin = d3.sum(MAJ, d => d.lost_min), pauMin = d3.sum(PAU, d => d.lost_min);
    readout('r-ep', `${MAJ.length} épisodes de 10 min ou plus · ${f0(majMin)} min`);
    $('ep-table').innerHTML = `<thead><tr><th class="n">#</th><th>Jour</th><th>Sortie</th><th class="n">km</th><th class="n">Réel / prévu</th><th class="n">Perdu</th><th>Cote</th><th>Cause</th></tr></thead><tbody>${MAJ.map((d, k) => {
      const r = rowOf(d.act), rs = RS[d.id];
      return `<tr title="${d.id}"><td class="n">${k + 1}</td><td class="mono">${dayLbl(d.day)}</td><td class="nw"><span class="dot" style="background:${d.sac ? C('--series-avec') : C('--series-sans')}" title="${d.sac ? 'avec le sac' : 'trail'}"></span>${r.name}</td>
        <td class="n">${f1(d.km0)}–${f1(d.km1)}<div class="muted">${f1(d.len)} km</div></td><td class="n">${f0(d.real_min)} / ${f0(d.real_min - d.lost_min)} min</td>
        <td class="n"><b>+${f0(d.lost_min)} min</b><span class="zbar" style="width:${Math.round(d.lost_min / MAJ[0].lost_min * 46)}px"></span></td>
        <td><span class="chipg l${d.grade}"><i></i>${GL[d.grade]}</span><div class="muted mono">pente ${d.slope > 0 ? '+' : ''}${f0(d.slope)} %</div></td>
        <td>${rs ? `<div class="causes">${rs.causes.map((c, j) => chip(c, !j)).join('')}${rs.certitude === 'probable' ? '<span class="est">probable</span>' : ''}</div><div class="cause-d">${rs.detail}</div>` : `<div class="causes"><span class="cause sec">non qualifié</span></div><div class="cause-d muted">Note de la sortie : ${r.note}</div>`}${d.alert.length ? `<div class="causes" style="margin-top:4px"><span class="tag"><svg viewBox="-8 -8 16 15"><path d="M0,-7 7,5.5 -7,5.5Z" fill="currentColor"/></svg>${d.alert.join(', ')}</span></div>` : ''}</td>
</tr>`;
    }).join('')}</tbody>`;
    $('ep-pause').innerHTML = `${PAU.length} épisodes plus courts, de 5 à 10 min chacun (${f0(pauMin)} min au total), ne sont pas détaillés : ce sont très probablement des pauses. Ils sont comptés dans le bilan sous « Autre · pause probable ».`;
    // minutes lost by main cause (costly episodes) + the probable pauses
    const mainOf = d => RS[d.id] ? RS[d.id].causes[0] : null;
    const groups = Object.keys(CAUSE).filter(k => k !== 'pause').map(k => ({ k, eps: MAJ.filter(d => mainOf(d) === k) })).filter(c => c.eps.length)
      .map(c => ({ k: c.k, min: d3.sum(c.eps, d => d.lost_min), n: c.eps.length })).sort((a, b) => b.min - a.min);
    const unq = MAJ.filter(d => !mainOf(d));
    const bars = groups.concat(unq.length ? [{ k: null, min: d3.sum(unq, d => d.lost_min), n: unq.length }] : [], PAU.length ? [{ k: 'pause', min: pauMin, n: PAU.length }] : []);
    const totMin = majMin + pauMin, col = c => c.k ? C(CAUSE[c.k][1]) : 'var(--surface-3)', lab = c => c.k ? CAUSE[c.k][0] : 'Non qualifié';
    $('cause-mix').innerHTML = `<div class="gm-bar">${bars.map(c => `<i style="flex:${c.min};background:${col(c)}" title="${lab(c)}"></i>`).join('')}</div>
      <div class="gm-rows">${bars.map(c => `<div class="gm-row"><i style="background:${col(c)}"></i><span>${lab(c)} <span class="mono">· ${c.n} épisode${c.n > 1 ? 's' : ''}</span></span><span class="mono">${f0(c.min)} min</span><span class="mono"><b>${f0(c.min / totMin * 100)} %</b></span></div>`).join('')}</div>`;
    const fam = d3.rollups(bars.filter(c => c.k), v => d3.sum(v, c => c.min), c => CAUSE[c.k][2]).sort((a, b) => b[1] - a[1]);
    if ($('cause-fam')) $('cause-fam').innerHTML = fam.map(([fm, mn]) => `<div class="gm-row"><span></span><span>${fm}</span><span class="mono">${f0(mn)} min</span><span class="mono"><b>${f0(mn / totMin * 100)} %</b></span></div>`).join('');
    readout('r-cause', `${slow.length} épisodes · ${f0(totMin)} min`);
    const fast = EPS.filter(d => d.sign < 0).sort((a, b) => a.lost_min - b.lost_min), fastOk = fast.filter(d => !d.gps);
    $('ep-fast').innerHTML = `Côté rapide, ${fast.length} épisodes rendent ${f0(-d3.sum(fastOk, d => d.lost_min))} min (hors pentes GPS douteuses). Les plus nets : ${fastOk.slice(0, 3).map(d => `${actName(d.act)} (${dayLbl(d.day)}, ${f0(-d.lost_min)} min)`).join(', ')}. ${(g => g.length ? `${g.join(' et ')} ${g.length > 1 ? 'sont écartés' : 'est écarté'} : une pente GPS de plus de 60 % fausse le temps attendu.` : '')(fast.filter(d => d.gps).map(d => actName(d.act)))}`;
    const top = groups[0], subi = d3.sum(fam.filter(([fm]) => /subi/.test(fm)), d => d[1]);
    const CL = EP.cluster;
    if (CL) $('lede-roll').innerHTML = `Chaque tronçon, pris seul, est ordinaire (partie 03). Ce qui compte, c’est leur ordre. Un <b>épisode</b>, c’est au moins 750 m d’affilée nettement plus lents (rouge) ou plus rapides (vert) que l’allure attendue. Si mes ${f0(D.n)} écarts étaient mélangés au hasard, on attendrait environ ${f0(CL.all.n)} épisodes lents de plus de 5 min, pour ${f0(CL.all.min)} min en tout. Il y en a <b>${CL.obs_n}</b>, qui coûtent <b>${f0(CL.obs_min)} min</b> : les tronçons lents s’enchaînent.`;
    $('t-roll').innerHTML = `<b>${MAJ.length}</b> épisodes de 10 min ou plus coûtent <b>${f0(majMin)} min</b>, et ${PAU.length} plus courts, sans doute des pauses, ${f0(pauMin)} min. Première cause : ${CAUSE[top.k][0].toLowerCase()} ; ${f0(subi / totMin * 100)} % du temps perdu est subi.${CL ? ` Même mélangés à l’intérieur de chaque sortie, les écarts n’en feraient que ${f0(CL.act.min)} min : la lenteur s’enchaîne au sein d’un même passage.` : ''}<br><br>Pourquoi ces enchaînements ? Parce que les sentiers des Lofoten ne ressemblent à aucun autre : on part du bord de la mer, on monte d’un coup, très raide, puis on redescend vers le fjord suivant. Un passage difficile ne dure pas un pas, il dure toute une montée ou toute une descente, et on ne peut pas en sortir au milieu. C’est la forme du relief qui fabrique ces enchaînements (partie 06).`;
  }

  /* ---------- 06 · independent summits, steep climbs: the risk structure of the massifs ---------- */
  function drawAcf() {
    const T = EP.topo, M = T.massifs, A = T.agg, sig = t => Math.abs(t.r) > t.crit;
    const med = k => d3.median(M, m => m[k]), steepD = d3.sum(T.slope.filter(b => b.lo >= 20), b => b.dist), steepG = d3.sum(T.slope.filter(b => b.lo >= 20), b => b.gain);
    const steepT = d3.sum(T.intens.filter((c, k) => T.slope[k].lo >= 20), c => c.time), flatI = T.intens[0], topI = T.intens[T.intens.length - 1];
    const worst = M.reduce((b, m) => m.lost > b.lost ? m : b, M[0]);
    {
      const B = T.slope, lab = b => b.hi == null ? `> ${b.lo} %` : `${b.lo}–${b.hi} %`;
      const f = frame('c-acf1', { t: 12, r: 44, b: 40, l: 8 });
      const x0 = d3.scaleBand().domain(B.map(lab)).range([0, f.w]).padding(.22);
      const x1 = d3.scaleBand().domain(['dist', 'gain']).range([0, x0.bandwidth()]).padding(.08);
      const y = d3.scaleLinear().domain([0, d3.max(B, b => Math.max(b.dist, b.gain)) * 1.1]).nice().range([f.h, 0]);
      yGrid(f.g, y, f.w, 4, v => `${f0(v * 100)} %`);
      const col = { dist: C('--text-muted'), gain: C('--down') };
      const gb = f.g.selectAll(null).data(B).join('g').attr('transform', b => `translate(${x0(lab(b))},0)`);
      ['dist', 'gain'].forEach(k => gb.append('path').attr('d', b => barPath(x1(k), f.h, x1.bandwidth(), y(b[k]))).attr('fill', col[k]).attr('opacity', k === 'dist' ? .55 : .9));
      hover(gb.append('rect').attr('class', 'hit').attr('width', x0.bandwidth()).attr('height', f.h), (b, k) => `<b>pente ${lab(b)}</b>${row('distance', `${f0(b.dist * 100)} %`)}${row('dénivelé positif', `${f0(b.gain * 100)} %`)}${row('vitesse verticale', `${f0(T.intens[B.indexOf(b)].vr)} m/h`)}${row('fréquence cardiaque', `${T.intens[B.indexOf(b)].hr} bpm`)}`);
      xAxis(f.g, x0, f.h, 7, d => f.narrow ? d.replace(' %', '').replace('> ', '>') : d);
      axTitle(f.g, f.narrow ? 'pente du tronçon (%)' : 'pente du tronçon', 0, f.h + 36);
      readout('r-acf1', `> 20 % : <b>${f0(steepD * 100)} %</b> de la distance · <b>${f0(steepG * 100)} %</b> du D+`);
      legend('l-acf1', [['', C('--text-muted'), 'part de la distance'], ['', C('--down'), 'part du dénivelé positif']]);
    }
    {
      const D = [
        { k: 'seg', l: 'Tronçons indépendants', s: 'hypothèse naïve', v: A.seg, c: C('--text-muted') },
        { k: 'massif', l: 'Massifs indépendants', s: 'Lofoten, mesuré', v: A.massif, c: C('--accent') },
        { k: 'block', l: 'Un seul bloc sans sortie', s: 'alpin, contrefactuel', v: A.block, c: C('--down') },
      ];
      const f = frame('c-acf2', { t: 16, r: 18, b: 34, l: 8 });
      const lw = Math.min(190, f.w * .42);
      const x = d3.scaleLinear().domain([0, A.block * 1.28]).range([0, f.w - lw]);
      const y = d3.scaleBand().domain(D.map(d => d.k)).range([0, f.h]).padding(.38);
      const g = f.g.append('g').attr('transform', `translate(${lw},0)`);
      g.append('g').attr('class', 'gridl').call(d3.axisBottom(x).ticks(4).tickSize(f.h).tickFormat('')).lower();
      g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(f.narrow ? 2 : 4).tickSize(0).tickPadding(8).tickFormat(v => `${v} min`));
      D.forEach(d => {
        f.g.append('text').attr('class', 'lbl-strong').attr('x', 0).attr('y', y(d.k) + y.bandwidth() / 2 - 3).text(d.l);
        f.g.append('text').attr('class', 'lbl').attr('x', 0).attr('y', y(d.k) + y.bandwidth() / 2 + 11).text(d.s);
        g.append('rect').attr('x', 0).attr('y', y(d.k)).attr('height', y.bandwidth()).attr('width', x(d.v)).attr('rx', 3).attr('fill', d.c).attr('opacity', d.k === 'massif' ? .95 : .6);
        g.append('text').attr('class', 'lbl-strong').attr('x', x(d.v) + 6).attr('y', y(d.k) + y.bandwidth() / 2).attr('dy', '.35em').text(`± ${f0(d.v)} min`);
      });
      // bloc d'explication en longueur, sous les deux graphiques
      const big = [...M].sort((a, b) => Math.abs(b.lost) - Math.abs(a.lost)).slice(0, 3);
      $('ex-intro').innerHTML = `On repart des minutes de la partie 05 : sur chaque tronçon, le temps réel moins le temps prévu par Tobler, en retard (+) ou en avance (−). Additionnées massif par massif, elles donnent par exemple ${big.map(m => `<b>${fs0(m.lost)} min</b> sur ${actName(m.act)}`).join(', ')}. Le graphique ne montre pas du temps perdu, mais une <b>incertitude</b> : de combien le temps total de la traversée peut s’écarter du prévu, selon la façon dont ces retards s’additionnent.`;
      $('ex-cols').innerHTML = D.map(d => `<div style="--c:${d.c}"><span class="s">${d.s}</span><div class="t">${d.l}</div><b class="v">± ${f0(d.v)} min</b><p>${{
        seg: 'Chaque tronçon est un tirage à part : un retard ici est compensé par une avance là. C’est l’hypothèse naïve, et elle est fausse : dans une même montée, si je suis lent sur un tronçon, je le suis aussi sur le suivant.',
        massif: 'Dans un massif, les retards s’accumulent sans se compenser : montée et descente vont dans le même sens. D’un massif à l’autre, ils se compensent : un sommet difficile n’en annonce pas un autre. C’est la structure réelle, mesurée.',
        block: 'Toute la traversée comme une seule arête sans retour en bas : les retards s’additionnent tous, sans aucune compensation. C’est un cas fictif, construit sur les mêmes minutes, pour comparer avec un enchaînement alpin.',
      }[d.k]}</p></div>`).join('');
      $('ex-msg').innerHTML = `<b>Les Lofoten sont un juste milieu.</b> Mieux que des tirages tous liés : chaque retour à la mer remet le compteur à zéro, et l’incertitude est ${f1(A.block / A.massif)} fois plus petite qu’un enchaînement sans sortie. Mais pas des tirages indépendants non plus : une fois dans un massif, on est engagé, et le modèle naïf sous-estime l’incertitude d’un facteur ${f1(A.massif / A.seg)}.`;
      readout('r-acf2', `sous-estimation naïve <b>×${f1(A.massif / A.seg)}</b> · diversification <b>×${f1(A.block / A.massif)}</b>`);
    }
    // risk sheet
    const rows = [
      ['Corrélation du terrain d’un massif au suivant', `raideur r = ${f2(T.grad_next.r)} · ${sig(T.grad_next) ? 'significatif' : 'non significatif'} (seuil ${f2(T.grad_next.crit)}, ${T.grad_next.n} paires)`,
        'Le terrain du massif suivant ne se déduit pas du précédent : un sommet difficile n’en annonce pas un autre.', 'Les massifs se tirent indépendamment : leurs risques se diversifient.'],
      ['Corrélation à l’intérieur d’un massif', `montée → descente : raideur r = ${f2(T.grad_same.r)} · allure r = ${f2(T.pace_same.r)}`,
        'Une fois engagé, tout le massif va dans le même sens : les écarts ne se compensent pas, ils s’additionnent jusqu’en bas.', `Tirer les erreurs par massif, pas par tronçon : l’écart-type du temps total passe de ± ${f0(A.seg)} à ± ${f0(A.massif)} min (×${f1(A.massif / A.seg)}). Les blocs de 2 km de la partie 11 vont dans ce sens.`],
      ['Facteur commun de la journée', `allure d’un massif au suivant r = ${f2(T.pace_next.r)}${sig(T.pace_next) ? ' · significatif' : ''}`,
        'Météo et forme du jour pèsent sur tous les massifs de la journée : c’est le risque systématique, il ne se diversifie pas.', 'Ajouter un facteur journée commun à tous les massifs du jour, l’équivalent d’un bêta de marché.'],
      ['Option de sortie', `retour à la mer en ${f0(med('t_exit'))} min médianes après le sommet (max ${f0(d3.max(M, m => m.t_exit))} min)`,
        `Chaque massif se termine au niveau de la mer : la perte d’une position est bornée, comme un stop-loss intégré. Pire massif : ${f0(worst.lost)} min perdues (${actName(worst.act)}).`, 'La queue de distribution se coupe massif par massif : une perte ne se propage pas au reste de la traversée.'],
      ['Durée d’engagement', `${f0(med('t_tot'))} min médianes par massif, dont ${f0(med('t_engage'))} min de montée à partir de 15 %`,
        `Positions courtes : la décision d’y aller ou de renoncer se reprend au pied de chacun des ${M.length} massifs.`, 'Renoncer est une option réelle, renouvelée à chaque massif : elle a de la valeur parce qu’on peut l’exercer sans compromettre la suite.'],
      ['Intensité (levier)', `> 20 % : ${f0(steepD * 100)} % de la distance, ${f0(steepT * 100)} % du temps, ${f0(steepG * 100)} % du D+ · ${f0(topI.vr)} m/h et ${topI.hr} bpm au-dessus de 30 %, contre ${f0(flatI.vr)} m/h et ${flatI.hr} bpm sur le plat`,
        'Le risque n’est pas réparti : il se concentre sur de courts passages très raides, où l’effort est maximal et où une erreur se paie cher.', 'La pente moyenne ne suffit pas : il faut modéliser la part du massif au-dessus de 20 % et l’effet propre des descentes raides (partie 07).'],
    ];
    $('risk-sheet').innerHTML = `<thead><tr><th>Indicateur</th><th>Mesure</th><th>Lecture risque</th><th>Conséquence pour le modèle</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${r[0]}</b></td><td class="mono rs-m">${r[1]}</td><td>${r[2]}</td><td class="muted">${r[3]}</td></tr>`).join('')}</tbody>`;
    readout('r-sheet', `${M.length} massifs · ${M.length - 1} retours à la mer`);
    const li = a => a.map(([h, p]) => `<li><b>${h}</b><span>${p}</span></li>`).join('');
    $('pc-pro').innerHTML = li([
      ['Diversification', `Des massifs indépendants s’additionnent en racine de la somme des carrés : ± ${f0(A.massif)} min sur la traversée, contre ± ${f0(A.block)} min si tout formait un seul bloc sans sortie.`],
      ['Perte bornée', `Chaque massif se solde au bord de la mer, ${f0(med('t_exit'))} min médianes après le sommet, avant d’engager le suivant.`],
      ['Décision renouvelée', `${M.length} points de décision : on peut renoncer au pied d’un massif sans compromettre le reste de l’itinéraire.`],
      ['Repli facile', 'Le niveau de la mer offre un terrain plat, des routes et des villages : se replier ne demande ni altitude ni col à franchir.'],
    ]);
    $('pc-con').innerHTML = li([
      ['Pas de compensation dans un massif', `Montée et descente vont dans le même sens (r = ${f2(T.pace_same.r)}) : à l’intérieur d’un massif, le risque est ${f1(A.massif / A.seg)} fois celui d’un modèle tronçon par tronçon.`],
      ['Risque systématique', `La journée reste un facteur commun (r = ${f2(T.pace_next.r)} d’un massif au suivant) : la météo ne se diversifie pas.`],
      ['Levier élevé', `${f0(steepG * 100)} % du dénivelé se gagne au-dessus de 20 %, sur ${f0(steepD * 100)} % de la distance : l’exposition est courte, mais concentrée.`],
      ['La sortie n’est pas gratuite', `On sort d’un massif par une descente aussi raide que la montée (r = ${f2(T.grad_same.r)}). La plus grosse perte de la traversée, ${actName(worst.act)}, s’est faite en descente.`],
    ]);
    $('t-acf').textContent = `La topographie des Lofoten transforme la traversée en une série de paris courts et indépendants. Le risque total se diversifie : ± ${f0(A.massif)} min sur l’ensemble, ${f1(A.block / A.massif)} fois moins qu’un enchaînement sans sortie, et chaque retour à la mer borne la perte. Mais chaque pari est à fort levier : ${f0(steepG * 100)} % du dénivelé au-dessus de 20 %, et une fois engagé, les écarts s’additionnent jusqu’en bas. La règle qui en découle : décider massif par massif, garder la marge pour la descente, et traiter la journée comme un facteur commun.`;
  }

  /* ---------- 07 · sensitivities (tornado) + correlation matrix ---------- */
  function drawSens() {
    const S = R.sens.slice().sort((a, b) => b.pct - a.pct), sLbl = n => n === 'pente (+10 %)' ? 'pente ↑ ou ↓ (+10 %)' : n;
    const f = frame('c-sens', { t: 12, r: 64, b: 32, l: 150 });
    const x = d3.scaleLinear().domain([-25, 50]).range([0, f.w]);
    const y = d3.scaleBand().domain(S.map(s => s.name)).range([0, f.h]).padding(.42);
    f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(6).tickSize(-f.h).tickFormat('')).lower();
    xAxis(f.g, x, f.h, f.narrow ? 3 : 6, v => `${v > 0 ? '+' : ''}${v} %`);
    f.g.append('line').attr('class', 'zero').attr('x1', x(0)).attr('x2', x(0)).attr('y1', -6).attr('y2', f.h);
    const sig = s => s.lo > 0 || s.hi < 0;
    const col = s => !sig(s) ? C('--text-muted') : s.pct > 0 ? C('--down') : C('--up');
    const r = f.g.selectAll('.sr').data(S).join('g').attr('transform', s => `translate(0,${y(s.name)})`);
    r.append('text').attr('class', 'lbl-strong').attr('x', -10).attr('y', y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(s => sLbl(s.name));
    r.append('rect').attr('x', s => x(Math.min(0, s.pct))).attr('width', s => Math.abs(x(s.pct) - x(0))).attr('height', y.bandwidth()).attr('rx', 2).attr('fill', col).attr('fill-opacity', .75);
    const mid = y.bandwidth() / 2;
    r.append('line').attr('x1', s => x(s.lo)).attr('x2', s => x(s.hi)).attr('y1', mid).attr('y2', mid).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2);
    ['lo', 'hi'].forEach(k => r.append('line').attr('x1', s => x(s[k])).attr('x2', s => x(s[k])).attr('y1', mid - 5).attr('y2', mid + 5).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2));
    r.append('text').attr('class', 'lbl-ink tagt').attr('x', s => x(Math.max(s.hi, 0)) + 8).attr('y', mid).attr('dy', '.35em').text(s => `${s.pct > 0 ? '+' : ''}${f1(s.pct)} %${sig(s) ? '' : ' n.s.'}`);
    hover(r.append('rect').attr('class', 'hit').attr('x', -150).attr('width', f.w + 210).attr('y', -y.step() * .2).attr('height', y.step()),
      s => `<b>${sLbl(s.name)}</b>${row('effet', `${s.pct > 0 ? '+' : ''}${f1(s.pct)} %`)}${row('IC 95 %', `${f1(s.lo)} à ${f1(s.hi)} %`)}${row('significatif', sig(s) ? 'oui' : 'non')}`);
    readout('r-sens', `R² <b>${f2(R.r2)}</b> · n <b>${R.series.length}</b> · MCO`);

    const V = R.corr.vars, M = R.corr.m, n = V.length;
    const cm = { t: 6, r: 6, b: 92, l: 86 };
    const c = frame('c-corr', cm);
    const s = Math.min(c.w, c.h) / n;
    const colS = d3.scaleLinear().domain([-1, 0, 1]).range([C('--div-neg'), C('--div-mid'), C('--div-pos')]).interpolate(d3.interpolateLab);
    const cells = [];
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) cells.push({ i, j, v: M[i][j] });
    c.g.selectAll('.cc').data(cells).join('rect').attr('x', d => d.j * s + .5).attr('y', d => d.i * s + .5).attr('width', s - 1).attr('height', s - 1).attr('fill', d => d.i === d.j ? C('--surface-3') : colS(d.v));
    if (s > 22) c.g.selectAll('.ct').data(cells.filter(d => d.i !== d.j)).join('text').attr('x', d => d.j * s + s / 2).attr('y', d => d.i * s + s / 2).attr('dy', '.35em').attr('text-anchor', 'middle')
      .attr('class', 'lbl').style('font-size', `${Math.min(10, s * .3)}px`).style('fill', d => Math.abs(d.v) > .5 ? '#fff' : C('--text-secondary')).text(d => F('.1f')(d.v).replace('−0,0', '0,0'));
    c.g.selectAll('.rl').data(V).join('text').attr('class', 'lbl').attr('x', -6).attr('y', (v, i) => i * s + s / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(v => v);
    c.g.selectAll('.cl').data(V).join('text').attr('class', 'lbl').attr('transform', (v, i) => `translate(${i * s + s / 2},${n * s + 6}) rotate(-45)`).attr('text-anchor', 'end').text(v => v);
    hover(c.g.selectAll('.ch').data(cells.filter(d => d.i !== d.j)).join('rect').attr('class', 'hit').attr('x', d => d.j * s).attr('y', d => d.i * s).attr('width', s).attr('height', s),
      d => `<b>${V[d.i]} × ${V[d.j]}</b>${row('ρ de Spearman', fs2(d.v))}`);
    const pente = sens['pente (+10 %)'], terr = sens['terrain (+1 niveau)'], desc = sens['descente raide (> 15 %)'], wind = sens['rafales (+10 km/h)'], fat = sens['fatigue (VFC −10 ms)'];
    // vitesses réelles en pente raide (15 à 25 %), montée contre descente : temps = Tobler × exp(e) × calage sur le temps en mouvement
    const tob = q => 6 * Math.exp(-3.5 * Math.abs(q.slope / 100 + .05)), dK = R.series.map((q, i) => q.km - (i ? R.series[i - 1].km : 0));
    const spd = sac => {
      const ix = d3.range(R.series.length).filter(i => R.series[i].sac === sac), T = i => dK[i] / tob(R.series[i]) * Math.exp(R.series[i].e);
      const cal = d3.sum(R.rows.filter(r => r.sac === sac), r => r.mov_h) / d3.sum(ix, T);
      const v = (lo, hi) => { const k = ix.filter(i => R.series[i].slope >= lo && R.series[i].slope < hi); return { n: k.length, v: d3.sum(k, i => dK[i]) / (d3.sum(k, T) * cal), t: d3.sum(k, i => dK[i]) / d3.sum(k, i => dK[i] / tob(R.series[i])) }; };
      return { up: v(15, 25), dn: v(-25, -15) };
    };
    const vT = spd(0), vS = spd(1);
    $('t-sens').innerHTML = `<b>Surprise : en pente raide, sans le sac, je monte plus vite que je ne descends</b> (${f1(vT.up.v)} contre ${f1(vT.dn.v)} km/h entre 15 et 25 %), l’inverse de Tobler. Passé un certain seuil, ce n’est plus la pente qui commande, mais le terrain : dans les Lofoten, peu de larges sentiers, surtout des pierriers, de la roche et parfois de l’escalade. En montée, mains et bâtons aident ; en descente, chaque appui se cherche (${fs0(desc.pct)} %). Le sac reste le premier frein (<b>${fs0(sacS.pct)} %</b>). La fatigue, elle, ne se voit pas dans l’allure : elle agit ailleurs (partie 08).`;
  }

  /* ---------- 08 · physical reserve (underwater curve) ---------- */
  function drawHrv() {
    // écart à la VFC habituelle (45 ms, mesurée hors traversée) : 0 % = nuit ordinaire
    const HRV_BASE = HRV_USUAL, BAND = .1;
    const N = R.nights.map(n => ({ ...n, dd_hrv: n.hrv / HRV_BASE - 1 }));
    const base = 0, lowB = -BAND, hiB = BAND;
    const m = { t: 20, r: 52, b: 24, l: 8 };
    const f = frame('c-hrv', m);
    const x = d3.scalePoint().domain(N.map((n, i) => i)).range([0, f.w]).padding(.5);
    const y = d3.scaleLinear().domain([-.6, .65]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${fs0(v * 100).replace('+0', '0')} %`);
    xAxis(f.g, x, f.h, null, i => f.narrow ? `${i + 1}` : N[i].camp.replace('Hauteurs de ', '').replace(' beach', ''));
    const st = d3.curveStepAfter, pts = [...N.map((n, i) => [x(i), n.dd_hrv]), [x(N.length - 1) + x.step() / 2, N[N.length - 1].dd_hrv]];
    const xs = pts.map(p => p[0]); xs[0] = x(0) - x.step() / 2;
    const P = pts.map((p, i) => [xs[i], p[1]]);
    // usual range (±10 % around the usual HRV), red only below it
    f.g.append('rect').attr('x', 0).attr('width', f.w).attr('y', y(hiB)).attr('height', y(lowB) - y(hiB)).attr('fill', C('--text-muted')).attr('opacity', .12);
    f.g.append('path').attr('d', d3.area().curve(st).x(p => p[0]).y0(y(lowB)).y1(p => y(Math.min(p[1], lowB)))(P)).attr('fill', C('--down')).attr('fill-opacity', .25);
    f.g.append('path').attr('d', d3.area().curve(st).x(p => p[0]).y0(y(hiB)).y1(p => y(Math.max(p[1], hiB)))(P)).attr('fill', C('--up')).attr('fill-opacity', .2);
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(base)).attr('y2', y(base)).attr('stroke', C('--text-secondary')).attr('stroke-dasharray', '5 4').attr('stroke-width', 1.2);
        if (!f.narrow) f.g.append('text').attr('class', 'lbl').attr('x', 4).attr('y', y(lowB) + 13).attr('text-anchor', 'start').text(`0 % = VFC habituelle ${HRV_BASE} ms · zone normale ±${f0(BAND * 100)} %`);
    f.g.append('path').attr('d', d3.line().curve(st).x(p => p[0]).y(p => y(p[1]))(P)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.6);
    f.g.selectAll('.hd').data(N).join('circle').attr('cx', (n, i) => x(i)).attr('cy', n => y(n.dd_hrv)).attr('r', 3.4).attr('fill', C('--bg')).attr('stroke', n => n.dd_hrv < lowB ? C('--down') : n.dd_hrv > hiB ? C('--up') : C('--text-primary')).attr('stroke-width', 1.6);
    const worst = N.reduce((a, b) => b.dd_hrv < a.dd_hrv ? b : a), wi = N.indexOf(worst);
    const best = N.reduce((a, b) => b.hrv > a.hrv ? b : a), bi = N.indexOf(best);
    axTag(f.g, f.w + 2, y(worst.dd_hrv), `${fs0(worst.dd_hrv * 100)} %`).select('rect').attr('fill', C('--down'));
    if (!f.narrow) {
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(wi) + 8).attr('y', y(worst.dd_hrv) + 16).text('nuit de 2 h → renoncement au Hermannsdalstinden');
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(bi) + 8).attr('y', y(best.dd_hrv) + 17).text(`${fs0(best.dd_hrv * 100)} % · bonne fatigue après le J1`);
      f.g.append('text').attr('class', 'lbl-strong').attr('x', x(0)).attr('y', y(N[0].dd_hrv) - 10).attr('text-anchor', 'middle').text('départ reposé');
    }
    hover(f.g.selectAll('.hh').data(N).join('rect').attr('class', 'hit').attr('x', (n, i) => x(i) - x.step() / 2).attr('width', x.step()).attr('y', 0).attr('height', f.h),
      n => `<b>${n.camp} · nuit du ${dateLbl(n.night)}</b>${row('VFC', `${n.hrv} ms`)}${row('écart à l’habitude', `${fs0(n.dd_hrv * 100)} %`)}${row('sommeil', hm(n.sleep_h))}${row('score', `${n.score}/100`)}${row('recharge', `${n.bb}/100`)}${row('FC au repos', `${n.fc} bpm`)}`);
    readout('r-hrv', `habituelle <b>${HRV_BASE} ms</b> · max <b>${best.hrv} ms</b> · min <b>${worst.hrv} ms</b> · écart min <b class="d">${fs0(worst.dd_hrv * 100)} %</b>`);

    const g = frame('c-sleep', { t: 8, r: 52, b: 22, l: 8 });
    const x2 = x.copy().range([0, g.w]);
    const y2 = d3.scaleLinear().domain([0, 11]).range([g.h, 0]);
    yGrid(g.g, y2, g.w, 2, v => `${v} h`);
    const bw = Math.min(18, x2.step() * .35);
    g.g.selectAll('.sb').data(N).join('path').attr('d', (n, i) => barPath(x2(i) - bw / 2, y2(0), bw, y2(n.sleep_h), 1.5)).attr('fill', n => n.sleep_h < 4 ? C('--warning') : C('--text-muted')).attr('fill-opacity', .8);
    g.g.selectAll('.stt').data(N).join('text').attr('class', 'lbl').attr('x', (n, i) => x2(i)).attr('y', n => y2(n.sleep_h) - 4).attr('text-anchor', 'middle').text(n => f1(n.sleep_h));
    xAxis(g.g, x2, g.h, null, i => g.narrow ? `${+N[i].night.slice(8)}` : dateLbl(N[i].night));
    const after = N.slice(wi + 1);
    const low = N.filter(n => n.hrv < HRV_BASE * (1 - BAND)), firstLow = low[0];
    $('t-hrv').innerHTML = `Le départ se fait dans des conditions idéales : la première nuit, à ${N[0].camp}, tombe pile sur ma VFC habituelle (${N[0].hrv} ms), reposé. Après la grosse première journée, elle grimpe à <b>${best.hrv} ms (${fs0(best.dd_hrv * 100)} %)</b> : une bonne fatigue, celle d’un corps qui encaisse sans rien accumuler encore. La rupture arrive à ${firstLow.camp} : <b>${firstLow.hrv} ms (${fs0(firstLow.dd_hrv * 100)} %)</b> après une nuit de ${hm(firstLow.sleep_h)}. Ensuite, elle ne revient jamais dans la zone normale (au mieux ${d3.max(after, n => n.hrv)} ms) : la réserve s’use sans se refaire. Pourtant, l’allure ne baisse pas (partie 07). La fatigue se voit dans les décisions : le Helvetestinden (J4) tombe après 1 h 15 de recherche de bivouac, le Hermannsdalstinden (J5) après la nuit de 2 h et une recharge de ${worst.bb}/100.`;
  }

  /* ---------- 09 bis · rain persistence, 2026 among 1 200 windows (risque_meteo.js, outils/meteo_series.js) ---------- */
  function drawPersist() {
    const M = window.RISK_METEO; if (!M) return;
    const pww = M.p_ww, pwd = M.p_wd, p = M.p_wet;

    // left: P(rain | yesterday)
    const f = frame('c-persist', { t: 26, r: 46, b: 30, l: 8 });
    const B = [{ k: 'veille sèche', v: pwd, n: M.n_wd }, { k: 'veille pluvieuse', v: pww, n: M.n_ww }];
    const x = d3.scaleBand().domain(B.map(b => b.k)).range([0, f.w]).padding(.45);
    const y = d3.scaleLinear().domain([0, .8]).range([f.h, 0]);
    yGrid(f.g, y, f.w, 4, v => `${f0(v * 100)} %`);
    xAxis(f.g, x, f.h, null, d => d);
    f.g.selectAll('.pb').data(B).join('path').attr('d', b => barPath(x(b.k), y(0), x.bandwidth(), y(b.v), 2)).attr('fill', (b, i) => i ? C('--down') : C('--accent')).attr('fill-opacity', .75);
    f.g.selectAll('.pt').data(B).join('text').attr('class', 'lbl-ink').attr('x', b => x(b.k) + x.bandwidth() / 2).attr('y', b => y(b.v) - 7).attr('text-anchor', 'middle').text(b => `${f0(b.v * 100)} %`);
    f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(p)).attr('y2', y(p)).attr('stroke', C('--text-secondary')).attr('stroke-dasharray', '5 4');
    f.g.append('text').attr('class', 'lbl').attr('x', 4).attr('y', y(p) - 5).text(`sans mémoire : ${f0(p * 100)} %`);
    hover(f.g.selectAll('.ph').data(B).join('rect').attr('class', 'hit').attr('x', b => x(b.k)).attr('width', x.bandwidth()).attr('y', 0).attr('height', f.h),
      b => `<b>Après une ${b.k}</b>${row('pluie le lendemain', `${f0(b.v * 100)} %`)}${row('jours observés', f0(b.n))}`);
    readout('r-persist', `×<b>${f1(pww / pwd)}</b> après un jour de pluie`);

    // right: one small histogram per question, 2026 marked
    const g = frame('c-strip', { t: 8, r: 8, b: 4, l: 8 });
    const S = [
      { k: 'Plus longue série sèche', o: M.dry, fmt: v => `${f0(v)} j`, tick: e => f0(e + .5), unit: 'j' },
      { k: 'Plus gros épisode de 3 jours', o: M.max3, fmt: v => `${f1(v)} mm`, tick: e => f0(e), unit: 'mm' },
    ];
    const rh = g.h / S.length;
    S.forEach((s, i) => {
      const o = s.o, E = o.edges, gg = g.g.append('g').attr('transform', `translate(0,${i * rh})`);
      const xx = d3.scaleLinear().domain([E[0], E[E.length - 1]]).range([0, g.w]), top = 22, base = rh - 22;
      const yy = d3.scaleLinear().domain([0, d3.max(o.hist)]).range([base, top]);
      gg.append('text').attr('class', 'lbl-strong').attr('x', 0).attr('y', 13).text(s.k);
      gg.append('text').attr('class', 'lbl-ink').attr('x', g.w).attr('y', 13).attr('text-anchor', 'end').text(`2026 : ${s.fmt(o.v)} · centile ${f0(o.pct)}`);
      const inBin = k => o.v >= E[k] && o.v < E[k + 1];
      gg.selectAll('.hb').data(o.hist).join('rect').attr('x', (n, k) => xx(E[k]) + .5).attr('width', (n, k) => Math.max(1, xx(E[k + 1]) - xx(E[k]) - 1)).attr('y', n => yy(n)).attr('height', n => base - yy(n))
        .attr('fill', (n, k) => inBin(k) ? C('--down') : C('--text-muted')).attr('fill-opacity', (n, k) => inBin(k) ? .9 : .5);
      gg.append('line').attr('x1', 0).attr('x2', g.w).attr('y1', base).attr('y2', base).attr('stroke', C('--grid'));
      const lo = s.unit === 'j' ? E[0] + .5 : E[0], hi = s.unit === 'j' ? E[E.length - 1] - .5 : E[E.length - 1];
      const tL = gg.append('text').attr('class', 'lbl').attr('x', 0).attr('y', base + 13).text(`${f0(lo)} ${s.unit}`);
      const tR = gg.append('text').attr('class', 'lbl').attr('x', g.w).attr('y', base + 13).attr('text-anchor', 'end').text(`${f0(hi)} ${s.unit}`);
      // médiane sur l'axe ; moyenne ajoutée dans la même étiquette si la place le permet
      const nb = v => Number.isInteger(v) ? f0(v) : f1(v), pm = xx(o.med);
      gg.append('line').attr('x1', pm).attr('x2', pm).attr('y1', top - 2).attr('y2', base + 3).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3').attr('opacity', .8);
      const lab = gg.append('text').attr('class', 'lbl').style('fill', C('--text-primary')).attr('y', base + 13);
      const put = txt => { lab.text(txt); const w = lab.node().getComputedTextLength(), x0 = Math.max(0, Math.min(g.w - w, pm - w / 2)); lab.attr('x', x0); return [x0, x0 + w]; };
      let [a0, a1] = put(`méd. ${nb(o.med)} · moy. ${nb(o.mean)} ${s.unit}`);
      const room = (l, r) => { const L = tL.node().getComputedTextLength(), R_ = g.w - tR.node().getComputedTextLength(); return l > L + 8 && r < R_ - 8; };
      if (!room(a0, a1)) [a0, a1] = put(`méd. ${nb(o.med)} ${s.unit}`);
      if (a0 < tL.node().getComputedTextLength() + 8) tL.remove();
      if (a1 > g.w - tR.node().getComputedTextLength() - 8) tR.remove();
      hover(gg.selectAll('.hh').data(o.hist).join('rect').attr('class', 'hit').attr('x', (n, k) => xx(E[k])).attr('width', (n, k) => xx(E[k + 1]) - xx(E[k])).attr('y', top).attr('height', base - top),
        (n, k) => `<b>${s.k}</b>${row(s.unit === 'j' ? 'durée' : 'pluie', s.unit === 'j' ? `${f0(E[k] + .5)} j` : `${f0(E[k])} à ${f0(E[k + 1])} mm`)}${row('fenêtres', `${n} sur ${M.n}`)}`);
    });
    legend('l-strip', [['', C('--text-muted'), 'fenêtres de 9 jours, 1996–2025'], ['', C('--down'), 'classe de 2026'], ['dash', '', 'médiane']]);
    readout('r-strip', `${f0(M.n)} fenêtres · départs ${M.starts}`);
    $('t-wx2').innerHTML = `<b>La pluie a de la mémoire</b> : après un jour de pluie, le lendemain est pluvieux ${f0(pww * 100)} % du temps, contre ${f0(pwd * 100)} % après un jour sec. Le beau temps arrive donc par séries, la pluie par épisodes. Sur la série sèche, j’ai eu un peu de chance, mais pas tant que ça : ${M.dry.v} jours secs d’affilée, centile ${f0(M.dry.pct)} ; ${f0(M.dry.ge / M.n * 100)} % des fenêtres de 9 jours en ont autant ou plus. L’épisode final, lui, était assez improbable : <b>${f1(M.ep.v)} mm en trois jours</b> au point de référence, centile ${f0(M.max3.pct)}, plus fort que ${f0(M.ep.pct)} % des épisodes de pluie de l’été (en moyenne ${f0(M.ep.mean)} mm). Ce calendrier m’a pourtant été favorable malgré la pluie : elle est arrivée à la fin, alors que j’avais presque atteint la côte. Entre chance et décision, on le verra dans la partie 14.`;
  }

  /* ---------- 09 · weather vs benchmark ---------- */
  function drawWx() {
    const Dd = W_.days;
    const m = { t: 14, r: 50, b: 26, l: 8 };
    const f = frame('c-rain', m);
    const x = d3.scaleLinear().domain([.6, 9.4]).range([0, f.w]);
    const y = d3.scaleLinear().domain([0, Math.max(W_.total_rain, W_.climato.pluie_mm) * 1.12]).nice().range([f.h, 0]);
    yGrid(f.g, y, f.w, 5, v => `${v} mm`);
    xAxis(f.g, x, f.h, 9, dayLbl);
    const bw = Math.min(14, f.w / 30);
    f.g.selectAll('.rb').data(Dd).join('path').attr('d', d => barPath(x(d.day) - bw / 2, y(0), bw, y(d.rain), 1.5)).attr('fill', C('--text-muted')).attr('fill-opacity', .45);
    // fine interpolation so the excess / deficit areas meet exactly where the lines cross
    const fine = []; for (let i = 0; i < Dd.length - 1; i++) for (let k = 0; k < 20; k++) { const u = k / 20, a = Dd[i], b = Dd[i + 1]; fine.push({ d: a.day + u, r: a.cum_rain + (b.cum_rain - a.cum_rain) * u, n: a.cum_norm + (b.cum_norm - a.cum_norm) * u }); }
    fine.push({ d: Dd[Dd.length - 1].day, r: Dd[Dd.length - 1].cum_rain, n: Dd[Dd.length - 1].cum_norm });
    f.g.append('path').attr('d', d3.area().x(p => x(p.d)).y0(p => y(p.n)).y1(p => y(Math.max(p.r, p.n)))(fine)).attr('fill', C('--down')).attr('fill-opacity', .28);
    f.g.append('path').attr('d', d3.area().x(p => x(p.d)).y0(p => y(p.n)).y1(p => y(Math.min(p.r, p.n)))(fine)).attr('fill', C('--up')).attr('fill-opacity', .2);
    const line = k => d3.line().x(d => x(d.day)).y(d => y(d[k]));
    f.g.append('path').attr('d', line('cum_norm')(Dd)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.4).attr('stroke-dasharray', '5 4');
    f.g.append('path').attr('d', line('cum_rain')(Dd)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 2);
    const last = Dd[Dd.length - 1];
    axTag(f.g, f.w + 2, y(last.cum_rain), f1(last.cum_rain)).select('rect').attr('fill', C('--accent'));
    axTag(f.g, f.w + 2, y(last.cum_norm), f1(last.cum_norm));
    // repère sur 1 200 fenêtres de 9 jours (risque_meteo.js), dans l'espace libre en haut à gauche
    const MM = window.RISK_METEO;
    if (MM) {
      const bx = f.g.append('g').attr('transform', 'translate(6,4)');
      bx.append('text').attr('class', 'lbl').attr('y', 10).text(f.narrow ? `Cumul de 9 j · ${f0(MM.n)} fenêtres` : `Cumul de 9 jours · ${f0(MM.n)} fenêtres 1996–2025 · point centre`);
      bx.append('text').attr('class', 'lbl-strong').attr('y', 27).text(`médiane ${f1(MM.tot.med)} mm · moyenne ${f1(MM.tot.mean)} mm`);
      bx.append('text').attr('class', 'lbl-ink').attr('y', 43).text(`2026 : ${f1(MM.tot.v)} mm · centile ${f0(MM.tot.pct)}`);
    }
    const ch = crossH(f);
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h).on('pointermove', ev => {
      const d = Dd[Math.max(0, Math.min(8, Math.round(x.invert(d3.pointer(ev)[0])) - 1))];
      ch.show(x(d.day), y(d.cum_rain), f1(d.cum_rain));
      showTip(ev, `<b>${dayLbl(d.day)} · ${dateLbl(d.date)}</b>${row('pluie du jour', `${f1(d.rain)} mm`)}${row('cumul vécu', `${f1(d.cum_rain)} mm`)}${row('cumul normal', `${f1(d.cum_norm)} mm`)}${row('écart', `${fs1(d.cum_rain - d.cum_norm)} mm`)}${row('températures', `${f1(d.tmin)} à ${f1(d.tmax)} °C`)}`);
    }).on('pointerleave', () => { ch.hide(); hideTip(); });
    legend('l-rain', [['ln', C('--accent'), 'cumul vécu'], ['dash', '', 'normale 1996–2025'], ['', C('--down'), 'excédent'], ['', C('--up'), 'déficit'], ['', C('--text-muted'), 'pluie du jour']]);
    readout('r-rain', `vécu <b>${f1(W_.total_rain)} mm</b> · normale <b>${f1(W_.climato.pluie_mm)}</b> · <b class="d">${fs0((W_.total_rain / W_.climato.pluie_mm - 1) * 100)} %</b>`);

    const g = frame('c-gust', { t: 14, r: 50, b: 26, l: 8 });
    const xg = x.copy().range([0, g.w]);
    const yg = d3.scaleLinear().domain([0, 90]).range([g.h, 0]);
    yGrid(g.g, yg, g.w, 4, v => `${v}`);
    xAxis(g.g, xg, g.h, 9, dayLbl);
    const ref = W_.climato.rafale;
    const fineG = []; for (let i = 0; i < Dd.length - 1; i++) for (let k = 0; k < 20; k++) { const u = k / 20; fineG.push({ d: Dd[i].day + u, v: Dd[i].gust + (Dd[i + 1].gust - Dd[i].gust) * u }); }
    fineG.push({ d: 9, v: Dd[8].gust });
    g.g.append('path').attr('d', d3.area().x(p => xg(p.d)).y0(yg(0)).y1(p => yg(p.v))(fineG)).attr('fill', C('--accent')).attr('fill-opacity', .08);
    g.g.append('path').attr('d', d3.area().x(p => xg(p.d)).y0(yg(ref)).y1(p => yg(Math.max(ref, p.v)))(fineG)).attr('fill', C('--down')).attr('fill-opacity', .35);
    g.g.append('path').attr('d', d3.line().x(d => xg(d.day)).y(d => yg(d.gust))(Dd)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 1.8);
    g.g.selectAll('.gd').data(Dd).join('circle').attr('cx', d => xg(d.day)).attr('cy', d => yg(d.gust)).attr('r', 3).attr('fill', d => d.gust > ref ? C('--down') : C('--accent')).attr('stroke', C('--bg')).attr('stroke-width', 1.2);
    g.g.append('line').attr('x1', 0).attr('x2', g.w).attr('y1', yg(ref)).attr('y2', yg(ref)).attr('stroke', C('--text-primary')).attr('stroke-width', 1.2).attr('stroke-dasharray', '5 4');
    axTag(g.g, g.w + 2, yg(ref), `${ref}`);
    hover(g.g.selectAll('.gh').data(Dd).join('rect').attr('class', 'hit').attr('x', d => xg(d.day - .5)).attr('width', xg(1.6) - xg(.6)).attr('y', 0).attr('height', g.h),
      d => `<b>${dayLbl(d.day)} · rafale max ${d.gust} km/h</b>${row('référence de la période', `${ref} km/h`)}${row('écart', `${fs0(d.gust - ref)} km/h`)}`);
    legend('l-gust', [['ln', C('--accent'), 'rafale max du jour (km/h)'], ['dash', '', 'rafale max normale'], ['', C('--down'), 'dépassement']]);
    readout('r-gust', `max <b>${W_.gust_max} km/h</b> · jours > réf. <b>${Dd.filter(d => d.gust > ref).length}</b>`);
    $('t-wx').textContent = `Six jours secs et plus chauds que la normale (${f1(W_.tmax_mean)} °C de max moyen contre ${f1(W_.climato.tmax)}), puis ${f1(lateRain)} mm en trois jours, soit ${f0((lateRain / W_.climato.pluie_mm - 1) * 100)} % de plus que la normale de toute la période, avec des rafales jusqu’à ${W_.gust_max} km/h. Les trois incidents de terrain les plus graves (escalade, éboulement, grotte) tombent dans ces trois jours, quand la VFC était déjà sous la zone normale (environ −30 %). Le nombre de jours de pluie est normal (${W_.rainy_days}) : c’est leur regroupement en fin de séjour qui a fait le risque.`;
  }

  /* ---------- 10 · danger scorecard ---------- */
  function drawIndex() {
    const rows = R.rows.slice().sort((a, b) => b.score - a.score);
    const mx = d3.max(rows, r => Math.abs(r.score));
    const keys = [['terrain', 'Terrain'], ['pente', 'Pente'], ['irreg', 'Irrég.'], ['meteo', 'Météo'], ['fatigue', 'Fatigue']];
    const col = d3.scaleLinear().domain([-.4, 0, .4]).range([C('--div-neg'), C('--div-mid'), C('--div-pos')]).interpolate(d3.interpolateLab).clamp(true);
    const pct = r => Math.round((1 - (r.rank - 1) / (rows.length - 1)) * 100);
    $('index-table').innerHTML = `<thead><tr><th class="n">#</th><th>Sortie</th><th>Jour</th><th>Cote</th><th>Indice</th><th class="n">Score</th><th class="n">Centile</th><th title="${keys.map(k => k[1]).join(' · ')}">Facteurs <span class="muted">T P I M F</span></th></tr></thead><tbody>${rows.map(r => {
      const w = Math.abs(r.score) / mx * 50;
      const bar = `<span class="sbar"><i style="${r.score >= 0 ? `left:50%;width:${w}%;background:var(--down)` : `right:50%;width:${w}%;background:var(--up)`};opacity:.8"></i></span>`;
      return `<tr><td class="n">${r.rank}</td><td class="nw"><span class="dot" style="background:${r.sac ? C('--series-avec') : C('--series-sans')}" title="${r.sac ? 'avec le sac' : 'trail'}"></span>${r.name}${r.alert.length ? `<svg class="alt-ic" viewBox="-8 -8 16 15" role="img"><title>Alerte : ${r.alert.join(', ')}</title><path d="M0,-7 7,5.5 -7,5.5Z" fill="currentColor"/></svg>` : ''}</td><td class="mono">${dayLbl(r.day)}</td><td><span class="chipg l${r.grade}"><i></i>${GL[r.grade]}</span></td><td style="min-width:150px">${bar}</td><td class="n">${fs2(r.score)}</td><td class="n">${pct(r)}</td>
        <td><span class="heat">${keys.map(([k, l]) => `<i style="background:${col(r.contrib[k])}" title="${l} ${fs2(r.contrib[k])}"></i>`).join('')}</span></td></tr>`;
    }).join('')}</tbody>`;
    legend('l-index', [['', C('--warning'), 'sortie avec alerte (survoler le triangle)'], ['', C('--series-avec'), 'avec le sac'], ['', C('--series-sans'), 'trail'], ['', C('--down'), 'au-dessus de la moyenne (plus exposé)'], ['', C('--up'), 'en dessous'], ['', C('--div-pos'), 'facteur aggravant'], ['', C('--div-neg'), 'facteur atténuant']]);
    readout('r-index', `Mann-Whitney <b>p = ${F('.3f')(R.idx.mw_p)}</b> · alertes <b>${R.idx.alert_ranks.join(', ')}</b>`);
    const logi = R.rows.filter(x => x.alert.length && !physIds.includes(x.id)).map(x => x.rank);
    const noAlertTop = rows.filter(x => !x.alert.length).slice(0, 2);
    $('t-index').innerHTML = `Construit sans regarder les incidents, l’indice les retrouve : les quatre alertes de terrain sortent aux rangs <b>${physRanks.join(', ')}</b> sur ${R.rows.length}, toutes dans le tiers le plus exposé (p = ${F('.3f')(R.idx.mw_p)}). L’alerte logistique (bivouac impossible) reste au milieu (rang ${logi.join(', ')}) : l’indice mesure le danger physique, pas les imprévus d’organisation. Deux sorties très exposées n’ont rien donné : ${noAlertTop.map(x => `${x.name} (${x.rank}e)`).join(' et ')}, le ${dayLbl(noAlertTop[0].day)}. Le danger était là, il n’a simplement rien coûté ce jour-là. Reste à mesurer jusqu’où une journée peut déraper : c’est la partie 11.`;
  }

  /* ---------- 11 · Monte Carlo ---------- */
  let mcModel = 'blocs', mcPlayed = false, mcRaf = 0;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  function drawMc(animate = false) {
    const K = MC.seg_km, other = mcModel === 'blocs' ? 'normal' : 'blocs';
    const M = MC[mcModel].seg, O = MC[other].seg;
    const el = $('c-mc'), narrow = el.clientWidth < 560;
    const histW = narrow ? 64 : 150;
    const m = { t: 22, r: histW + (narrow ? 34 : 118), b: 34, l: 46 };
    const f = frame('c-mc', m);
    const x = d3.scaleLinear().domain([0, K[K.length - 1]]).range([0, f.w]);
    const lim = Math.ceil(Math.max(M.term[6], -M.term[0], O.term[6], -O.term[0]) + .6);
    const y = d3.scaleLinear().domain([-lim, lim]).range([f.h, 0]);
    dayBands(f.g, x, f.h);
    yGrid(f.g, y, f.w, 6, v => `${v > 0 ? '+' : ''}${v} h`, 'left');
    xAxis(f.g, x, f.h, 8, v => `${v} km`);
    
    f.g.append('line').attr('class', 'zero').attr('x1', 0).attr('x2', f.w + histW + 8).attr('y1', y(0)).attr('y2', y(0));
    const col = d3.scaleLinear().domain([-lim * .7, 0, lim * .7]).range([C('--div-neg'), C('--text-muted'), C('--div-pos')]).interpolate(d3.interpolateLab).clamp(true);
    const pg = f.g.append('g');
    const band = (lo, hi) => d3.area().x((v, i) => x(K[i])).y0((v, i) => y(lo[i])).y1((v, i) => y(hi[i])).curve(d3.curveMonotoneX)(lo);
    const bandG = pg.append('g');   // percentile bands: they appear once the simulations are in
    bandG.append('path').attr('d', band(M.bands['5'], M.bands['95'])).attr('fill', C('--accent')).attr('opacity', .1);
    bandG.append('path').attr('d', band(M.bands['25'], M.bands['75'])).attr('fill', C('--accent')).attr('opacity', .14);
    const line = a => d3.line().x((v, i) => x(K[i])).y(v => y(Math.max(-lim, Math.min(lim, v))))(a);
    const pathG = pg.append('g');
    const simP = M.paths.map(p => pathG.append('path').attr('d', line(p)).attr('fill', 'none').attr('stroke', col(p[p.length - 1])).attr('stroke-width', .8).attr('opacity', .42));
    const lineG = pg.append('g');
    [['5', 1.6], ['95', 1.6], ['1', 1], ['99', 1]].forEach(([k, w]) => lineG.append('path').attr('d', line(M.bands[k])).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', w).attr('opacity', k === '1' || k === '99' ? .45 : .9));
    [O.bands['5'], O.bands['95']].forEach(a => lineG.append('path').attr('d', line(a)).attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.3).attr('stroke-dasharray', '5 4').attr('opacity', .9));
    const realP = pg.append('path').attr('d', line(MC.real_dev)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 2.6);
    // right margin: distribution of the arrival, rotated
    const hx = f.w + 10, H = M.hist, E = M.edges;
    const xh = d3.scaleLinear().domain([0, d3.max([...M.hist, ...O.hist])]).range([0, histW]);
    const hg = f.g.append('g').attr('transform', `translate(${hx},0)`);
    const bars = hg.selectAll('.mh').data(H.map((n, i) => ({ n, a: E[i], b: E[i + 1] })).filter(d => d.b > -lim && d.a < lim)).join('rect')
      .attr('y', d => y(Math.min(lim, d.b)) + .5).attr('height', d => Math.max(.5, y(Math.max(-lim, d.a)) - y(Math.min(lim, d.b)) - 1)).attr('x', 0).attr('rx', 1.5)
      .attr('width', d => animate ? 0 : xh(d.n)).attr('fill', d => col((d.a + d.b) / 2)).attr('opacity', .9);
    const cmpH = hg.append('path').attr('d', d3.line().curve(d3.curveStepAfter).x(d => xh(d.n)).y(d => y(d.a))(O.hist.map((n, i) => ({ n, a: E[i] })).filter(d => d.a >= -lim && d.a < lim)))
      .attr('fill', 'none').attr('stroke', C('--warning')).attr('stroke-width', 1.2).attr('stroke-dasharray', '4 3').attr('opacity', .9);
    const tags = [[M.term[5], `P95 ${F('+.1f')(M.term[5])} h`, 'lbl-ink'], [M.es95, `5 % pires ${F('+.1f')(M.es95)} h`, 'lbl-strong'], [M.term[1], `P5 ${F('+.1f')(M.term[1])} h`, 'lbl-ink']];
    const tagG = hg.append('g');
    if (!narrow) tags.forEach(([v, t, c], i) => {
      tagG.append('line').attr('x1', 0).attr('x2', histW + 6).attr('y1', y(v)).attr('y2', y(v)).attr('stroke', C('--text-primary')).attr('stroke-width', 1).attr('opacity', i === 1 ? .5 : .9);
      tagG.append('text').attr('class', `${c} mc-tag`).attr('x', histW + 10).attr('y', y(v) + (i === 1 ? -4 : 4)).text(t);
    });
    hg.append('text').attr('class', 'lbl').attr('x', 0).attr('y', -10).text(narrow ? 'arrivée' : 'distribution à l’arrivée');
    const lastR = MC.real_dev[MC.real_dev.length - 1];
    const lo = d3.minIndex(MC.real_dev), realL = f.g.append('g');
    realL.append('circle').attr('cx', x(K[lo])).attr('cy', y(MC.real_dev[lo])).attr('r', 4.5).attr('fill', C('--text-primary')).attr('stroke', C('--bg')).attr('stroke-width', 1.5);
    realL.append('text').attr('class', 'lbl-ink').attr('x', x(K[lo])).attr('y', y(MC.real_dev[lo]) + 20).attr('text-anchor', 'middle').text(`réel : ${hm(-MC.real_dev[lo])} d’avance au plus fort (${dayLbl(MC.seg_day[lo])})`);
    // crosshair
    const ch = f.g.append('line').attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted')).style('display', 'none');
    f.g.append('rect').attr('class', 'hit').attr('width', f.w).attr('height', f.h)
      .on('pointermove', ev => {
        const i = d3.minIndex(K, k => Math.abs(k - x.invert(d3.pointer(ev)[0])));
        ch.style('display', null).attr('x1', x(K[i])).attr('x2', x(K[i]));
        const b = k => F('+.2f')(M.bands[k][i]);
        showTip(ev, `<b>km ${f1(K[i])} · ${dayLbl(MC.seg_day[i])}</b>${row('P95 / P5', `${b('95')} / ${b('5')} h`)}${row('P75 / P25', `${b('75')} / ${b('25')} h`)}${row(other === 'normal' ? 'loi normale P95' : 'blocs P95', `${F('+.2f')(O.bands['95'][i])} h`)}${row('réel', `${F('+.2f')(MC.real_dev[i])} h`)}`);
      }).on('pointerleave', () => { ch.style('display', 'none'); hideTip(); });
    legend('l-mc', [['ln', C('--div-neg'), 'trajectoire en avance'], ['ln', C('--div-pos'), 'trajectoire en retard'], ['', C('--accent') + ';opacity:.4', 'P5–P95 et P25–P75'],
      ['ln', C('--text-primary'), 'trajectoire réelle'], ['dash', C('--warning'), `P5–P95 ${other === 'normal' ? 'loi normale' : 'blocs'} (comparaison)`]]);
    // animation: the simulations arrive one by one, faster and faster; each one runs the 159 km,
    // the counter and the arrival histogram fill as they land; then the percentiles and the real path
    cancelAnimationFrame(mcRaf);
    const cnt = $('mc-n'), fades = [bandG, lineG, cmpH, tagG, realL];
    const fullBars = () => bars.attr('width', d => xh(d.n));
    if (animate && !reduce) {
      const n = simP.length, T = 3800, len = simP.map(p => p.node().getTotalLength());
      const t0 = k => T * Math.pow(k / n, .55);          // gaps shrink: the run accelerates
      const run = k => 700 - 560 * (k / n);              // and each simulation crosses faster
      simP.forEach((p, k) => p.attr('stroke-dasharray', `${len[k]} ${len[k]}`).attr('stroke-dashoffset', len[k]).attr('opacity', 0));
      fades.forEach(g => g.attr('opacity', 0));
      const rl = realP.node().getTotalLength();
      realP.attr('stroke-dasharray', `${rl} ${rl}`).attr('stroke-dashoffset', rl);
      bars.attr('width', 0);
      const done = new Uint8Array(n), T0 = performance.now();
      const frame = now => {
        const t = now - T0; let landed = 0;
        for (let k = 0; k < n; k++) {
          if (done[k]) { landed++; continue; }
          const u = (t - t0(k)) / run(k);
          if (u < 0) continue;
          if (u >= 1) { done[k] = 1; landed++; simP[k].attr('stroke-dashoffset', 0).attr('stroke-dasharray', null).attr('opacity', .42).attr('stroke-width', .8); continue; }
          simP[k].attr('stroke-dashoffset', len[k] * (1 - d3.easeCubicOut(u))).attr('opacity', .95).attr('stroke-width', 1.4);
        }
        const frac = landed / n;
        cnt.textContent = f0(Math.round(frac * MC.ns));
        bars.attr('width', d => xh(d.n * frac));
        if (landed < n) { mcRaf = requestAnimationFrame(frame); return; }
        fullBars(); cnt.textContent = f0(MC.ns);
        fades.forEach((g, i) => g.transition().delay(i * 120).duration(500).attr('opacity', 1));
        realP.transition().delay(350).duration(1100).ease(d3.easeCubicInOut).attr('stroke-dashoffset', 0).on('end', () => realP.attr('stroke-dasharray', null));
      };
      mcRaf = requestAnimationFrame(frame);
    } else { fullBars(); cnt.textContent = f0(MC.ns); }
    // stats, table and text (both models side by side)
    const N_ = MC.normal.seg, B_ = MC.blocs.seg;
    $('mc-stats').innerHTML = [
      [`${hm(N_.term_sd)} → ${hm(B_.term_sd)}`, `écart-type à l’arrivée, loi normale → blocs (${fs0((B_.term_sd / N_.term_sd - 1) * 100)} %)`],
      [`${F('+.1f')(N_.term[5])} → ${F('+.1f')(B_.term[5])} h`, 'seuil à 95 % du retard à l’arrivée'],
      [`${F('+.1f')(N_.es95)} → ${F('+.1f')(B_.es95)} h`, 'retard moyen des 5 % pires scénarios'],
      [`${f1(pN)} → ${f1(pB)} %`, 'probabilité que le J3 dépasse 10 h de marche'],
    ].map(([b, s]) => `<div><b>${b}</b><span>${s}</span></div>`).join('');
    $('mc-table').innerHTML = `<thead><tr><th>Jour</th><th class="n">Réel</th><th class="n">P95 normale</th><th class="n">P95 blocs</th><th class="n">Moy. 5 % pires</th><th class="n">P(&gt; 10 h)</th></tr></thead><tbody>${MC.days.map((d, i) => `<tr${d === 3 ? ' style="font-weight:650"' : ''}><td>${dayLbl(d)}</td><td class="n">${hm(MC.real_day[i])}</td><td class="n">${hm(MC.normal.day_p95[i])}</td><td class="n">${hm(MC.blocs.day_p95[i])}</td><td class="n">${hm(MC.blocs.es95[i])}</td><td class="n">${MC.blocs.p_over10[i] ? `${f1(MC.normal.p_over10[i])} → ${f1(MC.blocs.p_over10[i])} %` : '–'}</td></tr>`).join('')}</tbody>`;
    const lowI = d3.minIndex(MC.real_dev);
    $('t-mc').textContent = `Le rééchantillonnage par blocs donne une dispersion à l’arrivée ${f0((B_.term_sd / N_.term_sd - 1) * 100)} % plus large que la loi normale, et un retard de ${F('+.1f')(B_.es95)} h dans les 5 % pires scénarios, contre ${F('+.1f')(N_.es95)} h. Sur la plus longue journée (J3), le risque de dépasser 10 h de marche passe de ${f1(pN)} % à ${f1(pB)} %, soit ${f0(pB / pN)} fois plus. La trajectoire réelle a compté jusqu’à ${hm(-MC.real_dev[lowI])} d’avance (km ${f0(K[lowI])}, ${dayLbl(MC.seg_day[lowI])}) avant que les J7 à J9, sous la pluie, la ramènent au centre : une marge calculée sur la moyenne aurait été consommée sans être vue.`;
  }
  function initMc() {
    document.querySelectorAll('.segctl button').forEach(b => b.addEventListener('click', () => {
      mcModel = b.dataset.m;
      document.querySelectorAll('.segctl button').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
      drawMc(true);
    }));
    $('mc-replay').addEventListener('click', () => drawMc(true));
    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting) && !mcPlayed) { mcPlayed = true; drawMc(true); io.disconnect(); } }, { threshold: .35 });
    io.observe($('c-mc'));
  }

  /* ---------- 12 · speed vs irregularity (quadrants) ---------- */
  function drawScatter() {
    const P = R.scatter;
    const f = frame('c-scatter', { t: 14, r: 50, b: 34, l: 8 });
    const x = d3.scaleLinear().domain([d3.min(P, p => p.x) - .02, d3.max(P, p => p.x) + .03]).range([0, f.w]);
    const y = d3.scaleLinear().domain([d3.min(P, p => p.y) - .4, d3.max(P, p => p.y) + .6]).range([f.h, 0]);
    const rr = d3.scaleSqrt().domain([0, d3.max(P, p => p.d)]).range([3, f.narrow ? 15 : 22]);
    const mx = d3.median(P, p => p.x), my = d3.median(P, p => p.y);
    f.g.append('rect').attr('x', 0).attr('y', 0).attr('width', x(mx)).attr('height', y(my)).attr('fill', C('--up')).attr('opacity', .05);
    f.g.append('rect').attr('x', x(mx)).attr('y', y(my)).attr('width', f.w - x(mx)).attr('height', f.h - y(my)).attr('fill', C('--down')).attr('opacity', .05);
    yGrid(f.g, y, f.w, 5, F('.0f'));
    f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(6).tickSize(-f.h).tickFormat('')).lower();
    xAxis(f.g, x, f.h, 6, F('.2f'));
    axTitle(f.g, 'irrégularité σ(e)', 0, f.h + 30);
    [[x(mx), 0, x(mx), f.h], [0, y(my), f.w, y(my)]].forEach(([a, b, c, d]) => f.g.append('line').attr('x1', a).attr('y1', b).attr('x2', c).attr('y2', d).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '3 4'));
    if (!f.narrow) [['RAPIDE · RÉGULIER', 6, 14, 'start'], ['RAPIDE · IRRÉGULIER', f.w - 6, 14, 'end'], ['LENT · RÉGULIER', 6, f.h - 8, 'start'], ['LENT · IRRÉGULIER', f.w - 6, f.h - 8, 'end']]
      .forEach(([t, a, b, an]) => f.g.append('text').attr('class', 'ax-title').attr('x', a).attr('y', b).attr('text-anchor', an).text(t));
    f.g.append('path').attr('d', d3.line().curve(d3.curveStepAfter).x(p => x(p[0])).y(p => y(p[1]))(R.front)).attr('fill', 'none').attr('stroke', C('--text-secondary')).attr('stroke-width', 1.3);
    const S = [...P].sort((a, b) => b.d - a.d);
    f.g.selectAll('.bb').data(S).join('circle').attr('cx', p => x(p.x)).attr('cy', p => y(p.y)).attr('r', p => rr(p.d))
      .attr('fill', p => p.sac ? C('--series-avec') : C('--series-sans')).attr('fill-opacity', .6).attr('stroke', p => p.alert ? C('--warning') : (p.sac ? C('--series-avec') : C('--series-sans'))).attr('stroke-width', p => p.alert ? 2.2 : 1);
    const lab = P.filter(p => p.alert || p.y === d3.max(P, q => q.y) || p.id === 'reinebringen_helvete');
    if (!f.narrow) f.g.selectAll('.bl').data(lab).join('text').attr('class', 'lbl-strong').attr('x', p => x(p.x) + rr(p.d) + 4).attr('y', p => y(p.y) + 4).text(p => p.name.replace('Reinebringen / Helvete', 'Reinebringen–Helvete').replace(/\s*\(.*\)/, ''));
    hover(f.g.selectAll('.bh').data(S).join('circle').attr('class', 'hit').attr('cx', p => x(p.x)).attr('cy', p => y(p.y)).attr('r', p => Math.max(10, rr(p.d))),
      p => `<b>${p.name} · ${dayLbl(p.day)}</b>${row('vitesse d’effort', `${f2(p.y)} km-effort/h`)}${row('irrégularité', f2(p.x))}${row('D+', `${f0(p.d)} m`)}${row('mode', p.sac ? 'avec le sac' : 'trail')}`);
    legend('l-scatter', [['', C('--series-avec'), 'avec le sac'], ['', C('--series-sans'), 'sans sac (trail)'], ['ring', C('--warning'), 'sortie avec alerte'], ['ln', C('--text-secondary'), 'meilleure vitesse par niveau d’irrégularité']]);
    readout('r-scatter', `médianes σ <b>${f2(mx)}</b> · <b>${f1(my)}</b> km-effort/h`);
    const al = P.filter(p => p.alert), right = al.filter(p => p.x > mx).length;
    const mA = d3.mean(P.filter(p => p.sac), p => p.y), mS = d3.mean(P.filter(p => !p.sac), p => p.y);
    $('t-scatter').textContent = `Avec le sac, les sorties sont groupées en bas : lentes (${f1(mA)} km-effort/h en moyenne) mais assez régulières. Sans le sac, elles montent et s’étalent : ${f1(mS)} km-effort/h, au prix d’une plus grande dispersion. ${right} des ${al.length} sorties à alerte sont à droite de la médiane : gagner en vitesse sans sac, c’est aussi accepter des allures moins prévisibles.`;
  }

  /* ---------- 13 · plan vs actual ---------- */
  const PLAN = [
    [1, '14/06', 'Napp → Nusfjord, sommet du Tønnåsheia', 'Napp → Nusfjord. Tønnåsheia abandonné : le premier jour avec le sac est bien plus dur que prévu.', [['c-ren', 'Renoncement']]],
    [2, '15/06', 'Volandstinden, bivouac sur son versant ou à Fredvang', 'Volandstinden, puis au-delà de Fredvang jusqu’aux hauteurs de Kvalvika, pour enchaîner sur le Ryten.', [['c-av', 'Avance volontaire']]],
    [3, '16/06', 'Ryten, Kvalvika, Kitinden, bivouac au pied du Kitinden', 'Ryten (brouillard), plage, Moltinden à la place du Kitinden. Camp impossible au lac : la journée continue jusqu’à Horseid.', [['c-av', 'Avance subie'], ['c-sub', 'Substitution']]],
    [4, '17/06', 'Horseid → bateau de 15 h → Bunes, Helvetestinden', 'Bivouac à Bunes imposé par le bateau. Helvetestinden abandonné après 1 h 15 de recherche de bivouac.', [['c-ren', 'Renoncement']]],
    [5, '18/06', 'Repos : jusqu’à Munkebu, Munken en bonus', 'Plan révisé pour regagner un jour : départ à 2 h après 2 h de sommeil, puis craquage au pied du Hermannsdalstinden. Munkebu et Munken comme prévu.', [['c-ren', 'Renoncement'], ['c-ok', 'Plan initial tenu']]],
    [6, '19/06', 'Journée 100 % trail depuis Munkebu : Hermannsdalstinden aller-retour', 'Reine, Reinebringen, l’arête, Helvete : 21 km, 1 677 m de D+.', [['c-ok', 'Contenu remplacé']]],
    [7, '20/06', 'Jusqu’à Å, Andstabben, début du tour du lac', 'Camp fixe à Sørvågen sous la pluie. Å et Andstabben en trail. Tour du lac abandonné (déconseillé, météo).', [['c-ab', 'Abandon d’itinéraire']]],
    [8, '21/06', 'Fin du tour du lac, puis camp sur les hauteurs de Sørvågen, au plus près du port', 'Le jour de marge est avancé et sert à la Støvla : neige après la barre rocheuse, éboulement au retour.', [['c-ok', 'Marge utilisée']]],
    [9, '22/06', 'Jour de marge (météo ou forme) : Støvla ou kayak, puis le port', 'Gylttinden partiel, arrêt dans la grotte après les 10 000 m de D+. Kayak impossible.', [['c-sub', 'Jour réaffecté']]],
  ];
  const PL = window.RISK_PLAN;
  const planDay = d => PL && PL.plan.days.find(x => x.day === d), realDay = d => PL && PL.real.days.find(x => x.day === d);
  function drawPlan() {
    const fk = v => `${v > 0 ? '+' : v < 0 ? '−' : '±'}${f1(Math.abs(v))} km`, fm = v => `${v > 0 ? '+' : v < 0 ? '−' : '±'}${f0(Math.abs(v))} m`;
    $('plan').innerHTML = `<thead><tr><th>Jour</th><th>Prévu</th><th>Réel</th><th class="n">Écart</th><th>Statut</th></tr></thead><tbody>${PLAN.map(([d, dt, p, r, chips]) => {
      const pd = planDay(d), rd = realDay(d);
      const num = (x, sm) => x ? `<div class="pnum mono">${f1(x.km)} km · ${f0(x.dplus)} m D+${sm && sm.length ? ` · ${sm.join(', ')}` : ''}</div>` : '';
      return `<tr><td>J${d}<br><span class="muted">${dt}</span></td><td>${p}${num(pd, pd && pd.summits)}</td><td>${r}${num(rd, rd && rd.summits)}</td>
        <td class="n">${pd && rd ? `${fk(rd.km - pd.km)}<div class="muted">${fm(rd.dplus - pd.dplus)}</div>` : ''}</td><td><span class="chips">${chips.map(([c, t]) => `<span class="chip ${c}">${t}</span>`).join('')}</span></td></tr>`;
    }).join('')}</tbody>`;
    const cnt = k => PLAN.reduce((n, p) => n + p[4].filter(c => c[0] === k).length, 0);
    readout('r-plan', `renoncements <b>${cnt('c-ren')}</b> · substitution <b>${cnt('c-sub')}</b> · abandon <b>${cnt('c-ab')}</b>`);
    if (!PL) return;
    const M = PL.match, P_ = PL.plan, Rl = PL.real;
    const totR = M.bridge.find(b => b.k === 'real').v, dpR = totDp;
    $('plan-lede').textContent = `Le plan, c’est 8 jours d’itinéraire et 1 jour de marge. L’itinéraire tracé avant le départ fait ${f1(P_.km8)} km à pied (hors bateau, avec l’aller-retour au Hermannsdalstinden depuis Munkebu), ${d3.sum(P_.days, d => d.summits.length) - 1} sommets et le tour du lac d’Å. Le jour de marge, prévu pour la météo ou la forme, a servi à la Støvla : ${f1(P_.margin.km)} km de plus. Le plan complet fait donc ${f1(P_.km_walk)} km et ${f0(P_.dplus)} m de dénivelé, sur les mêmes 9 jours que la traversée réelle : ${f1(totR)} km et ${f0(dpR)} m. Ce qui suit explique l’écart, jour par jour.`;
    // planned summits
    const ab = n => M.abandoned.find(a => a.name === n);
    const SUM = [
      ['J1', 'Tønnåsheia', 'ab', 'Abandonné : premier jour avec le sac plus dur que prévu'],
      ['J2', 'Volandstinden', 'ok', 'Fait'],
      ['J3', 'Ryten', 'ok', 'Fait, dans le brouillard, au réveil depuis le camp'],
      ['J3', 'Kitinden', 'sub', 'Remplacé par le Moltinden'],
      ['J4', 'Helvetestinden', 'ab', 'Abandonné après 1 h 15 de recherche de bivouac sur son sentier'],
      ['J5', 'Munken', 'ok', 'Fait, en soirée depuis Munkebu'],
      ['J6', 'Hermannsdalstinden', 'ab', 'Abandonné au pied, après la nuit de 2 h ; journée Reinebringen–Helvete à la place'],
      ['J7', 'Andstabben', 'ok', 'Fait, en trail depuis Sørvågen'],
      ['J7–J8', 'Tour du lac', 'ab', 'Abandonné : déconseillé sur place, météo ; Støvla à la place'],
      ['J9', 'Støvla (jour de marge)', 'ok', 'Fait au J8 : la marge avance d’un jour après l’abandon du tour du lac ; le J9 sert au Gylttinden'],
    ];
    const chipS = { ok: ['c-ok', 'fait'], ab: ['c-ab', 'abandonné'], sub: ['c-sub', 'remplacé'] };
    $('plan-sum').innerHTML = `<thead><tr><th>Jour</th><th>Prévu</th><th>Statut</th><th class="n">Non fait</th></tr></thead><tbody>${SUM.map(([d, n, k, t]) => { const a = ab(n);
      return `<tr><td class="mono">${d}</td><td><b>${n}</b><div class="muted">${t}</div></td><td><span class="chip ${chipS[k][0]}">${chipS[k][1]}</span></td><td class="n">${a ? `${f1(a.km)} km<div class="muted">${f0(a.top)} m</div>` : ''}</td></tr>`; }).join('')}</tbody>`;
    readout('r-psum', `${SUM.filter(x => x[2] === 'ok').length} faits · ${SUM.filter(x => x[2] === 'ab').length} abandonnés · ${SUM.filter(x => x[2] === 'sub').length} remplacés`);
    // bivouacs: planned vs real camp, and the bivouac search episodes
    const hav = (a, b) => { const la = (b[0] - a[0]) * Math.PI / 180, lo = (b[1] - a[1]) * Math.PI / 180 * Math.cos(a[0] * Math.PI / 180); return 6371 * Math.hypot(la, lo); };
    const bivN = P_.camps.map((c, i) => ({ p: c, r: Rl.camps[i] })).slice(1);
    const searches = M.biv;
    $('plan-biv').innerHTML = `<thead><tr><th>Nuit</th><th>Prévu</th><th>Réel</th><th class="n">Écart</th></tr></thead><tbody>${bivN.map(({ p, r }) => {
      const d = hav([p.lat, p.lon], [r.lat, r.lon]), da = r.alt - p.alt;
      return `<tr><td class="mono">${dateLbl(p.night)}</td><td>${p.name}${p.est ? '<span class="est">estimé</span>' : ''}<div class="muted mono">${f0(p.alt)} m</div></td><td>${r.name}<div class="muted mono">${f0(r.alt)} m</div></td><td class="n">${d < .3 ? 'même lieu' : `${f1(d)} km`}<div class="muted">${fm(da)}</div></td></tr>`;
    }).join('')}</tbody>`;
    readout('r-pbiv', `recherche de bivouac : <b>${f1(d3.sum(searches, x => x.km))} km</b> · <b>+${f0(d3.sum(searches, x => x.up))} m</b>`);
  }
  function drawPlanCharts() {
    if (!PL) return;
    const P_ = PL.plan, Rl = PL.real, M = PL.match;
    // ---- map
    {
      const f = frame('c-pmap', { t: 10, r: 10, b: 10, l: 10 });
      const all = [...P_.line.flat(), ...Rl.line.flat()];
      const lat0 = d3.mean(all, p => p[1]), kx = Math.cos(lat0 * Math.PI / 180);
      const xs = d3.extent(all, p => p[0] * kx), ys = d3.extent(all, p => p[1]);
      const sc = Math.min(f.w / (xs[1] - xs[0]), f.h / (ys[1] - ys[0]));
      const ox = (f.w - (xs[1] - xs[0]) * sc) / 2, oy = (f.h - (ys[1] - ys[0]) * sc) / 2;
      const X = p => ox + (p[0] * kx - xs[0]) * sc, Y = p => f.h - oy - (p[1] - ys[0]) * sc;
      const ln = d3.line().x(X).y(Y);
      Rl.line.forEach(l => f.g.append('path').attr('d', ln(l)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 2).attr('opacity', .85).attr('stroke-linejoin', 'round'));
      P_.line.forEach(l => f.g.append('path').attr('d', ln(l)).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-width', 1.3).attr('stroke-dasharray', '4 3').attr('opacity', .75));
      // boat
      const a = P_.line[0][P_.line[0].length - 1], b = P_.line[1][0];
      f.g.append('path').attr('d', ln([a, b])).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '1 4').attr('stroke-width', 1.5).attr('fill', 'none');
      f.g.append('text').attr('class', 'lbl').attr('x', (X(a) + X(b)) / 2 + 8).attr('y', (Y(a) + Y(b)) / 2).text('bateau');
      const uniq = arr => arr.filter((c, i) => arr.findIndex(x => x.name === c.name) === i);
      const pc = uniq(P_.camps), rc = uniq(Rl.camps);
      hover(f.g.selectAll(null).data(pc).join('rect').attr('x', c => X([c.lon, c.lat]) - 5).attr('y', c => Y([c.lon, c.lat]) - 5).attr('width', 10).attr('height', 10)
        .attr('fill', C('--bg')).attr('stroke', C('--text-primary')).attr('stroke-width', 1.6), c => `<b>Prévu · ${c.name}</b>${row('nuit', P_.camps.filter(x => x.name === c.name).map(x => dateLbl(x.night)).join(', '))}${row('altitude', `${f0(c.alt)} m`)}${c.est ? row('position', 'estimée') : ''}`);
      hover(f.g.selectAll(null).data(rc).join('circle').attr('cx', c => X([c.lon, c.lat])).attr('cy', c => Y([c.lon, c.lat])).attr('r', 5.5)
        .attr('fill', C('--accent')).attr('stroke', C('--bg')).attr('stroke-width', 1.5), c => `<b>Réel · ${c.name}</b>${row('nuit', Rl.camps.filter(x => x.name === c.name).map(x => dateLbl(x.night)).join(', '))}${row('altitude', `${f0(c.alt)} m`)}`);
      if (!f.narrow) rc.forEach(c => f.g.append('text').attr('class', 'lbl-strong').attr('x', X([c.lon, c.lat]) + 9).attr('y', Y([c.lon, c.lat]) + 4).text(c.name.replace('Hauteurs de ', '').replace(' beach', '')));
      readout('r-pmap', `plan <b>${f1(P_.km_walk)} km</b> avec la marge · réel <b>${f1(M.bridge.find(b => b.k === 'real').v)} km</b>`);
      legend('l-pmap', [['dash', C('--text-primary'), 'itinéraire prévu'], ['ln', C('--accent'), 'trace réelle'], ['ring', C('--text-primary'), 'campement prévu'], ['', C('--accent'), 'campement réel']]);
    }
    // ---- progress on the planned route, evening after evening
    {
      const N = P_.camps.map((c, i) => ({ night: c.night, plan: c.km, real: Rl.camps[i].plan_km, pname: c.name, rname: Rl.camps[i].name }));
      const f = frame('c-prog', { t: 16, r: 54, b: 34, l: 8 });
      const x = d3.scalePoint().domain(N.map((n, i) => i)).range([0, f.w]).padding(.4);
      const y = d3.scaleLinear().domain([0, P_.km_total]).nice().range([f.h, 0]);
      yGrid(f.g, y, f.w, 6, v => `${v} km`);
      xAxis(f.g, x, f.h, null, i => dateLbl(N[i].night));
      const st = d3.line().curve(d3.curveStepAfter).x((n, i) => x(i)).y(v => y(v));
      // shaded gap between the two
      f.g.append('path').attr('d', d3.area().curve(d3.curveStepAfter).x((n, i) => x(i)).y0(n => y(n.plan)).y1(n => y(n.real))(N)).attr('fill', C('--accent')).attr('opacity', .12);
      f.g.append('path').attr('d', st(N.map(n => n.plan))).attr('fill', 'none').attr('stroke', C('--text-primary')).attr('stroke-dasharray', '5 4').attr('stroke-width', 1.5);
      f.g.append('path').attr('d', st(N.map(n => n.real))).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 2.2);
      f.g.selectAll(null).data(N).join('circle').attr('cx', (n, i) => x(i)).attr('cy', n => y(n.real)).attr('r', 3.8).attr('fill', C('--accent'));
      f.g.selectAll(null).data(N).join('rect').attr('x', (n, i) => x(i) - 3.5).attr('y', n => y(n.plan) - 3.5).attr('width', 7).attr('height', 7).attr('fill', C('--bg')).attr('stroke', C('--text-primary')).attr('stroke-width', 1.4);
      N.forEach((n, i) => { const d = n.real - n.plan; if (Math.abs(d) < 1.5) return;
        f.g.append('text').attr('class', 'lbl-strong').attr('x', x(i) + 6).attr('y', y(Math.max(n.real, n.plan)) - 8).text(`${d > 0 ? '+' : '−'}${f0(Math.abs(d))} km`).attr('fill', d > 0 ? C('--up') : C('--down')); });
      hover(f.g.selectAll(null).data(N).join('rect').attr('class', 'hit').attr('x', (n, i) => x(i) - x.step() / 2).attr('width', x.step()).attr('y', 0).attr('height', f.h),
        n => `<b>Nuit du ${dateLbl(n.night)}</b>${row('prévu', `${n.pname} · km ${f1(n.plan)}`)}${row('réel', `${n.rname} · km ${f1(n.real)}`)}${row('écart', `${n.real - n.plan >= 0 ? '+' : '−'}${f1(Math.abs(n.real - n.plan))} km`)}`);
      const best = N.reduce((b, n) => n.real - n.plan > b.real - b.plan ? n : b, N[0]);
      readout('r-prog', `avance max <b>+${f0(best.real - best.plan)} km</b> (${dateLbl(best.night)})`);
      legend('l-prog', [['dash', C('--text-primary'), 'campements prévus'], ['ln', C('--accent'), 'campements réels, placés sur le parcours prévu']]);
    }
    // ---- bridge from planned to real distance
    {
      const B = M.bridge, f = frame('c-bridge', { t: 8, r: 70, b: 28, l: 8 });
      const lw = Math.min(250, f.w * .42);
      let run = 0; const D = B.map(b => { if (b.k === 'plan' || b.k === 'real') { run = b.v; return { ...b, a: 0, z: b.v }; } const a = run; run += b.v; return { ...b, a, z: run }; });
      const x = d3.scaleLinear().domain([0, d3.max(D, d => Math.max(d.a, d.z)) * 1.04]).range([0, f.w - lw]);
      const y = d3.scaleBand().domain(D.map(d => d.k)).range([0, f.h]).padding(.28);
      const g = f.g.append('g').attr('transform', `translate(${lw},0)`);
      g.append('g').attr('class', 'gridl').call(d3.axisBottom(x).ticks(6).tickSize(f.h).tickFormat('')).lower();
      g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(6).tickSize(0).tickPadding(8).tickFormat(v => `${v} km`));
      const col = d => ({ plan: C('--accent'), cal: C('--series-avec'), dec: d.v < 0 ? C('--up') : C('--down'), ter: C('--warning'), mes: C('--text-muted') })[d.g];
      D.forEach((d, i) => {
        f.g.append('text').attr('class', d.k === 'plan' || d.k === 'real' ? 'lbl-strong' : 'lbl').attr('x', 0).attr('y', y(d.k) + y.bandwidth() / 2).attr('dy', '.35em').text(d.l);
        g.append('rect').attr('x', x(Math.min(d.a, d.z))).attr('width', Math.max(1.5, Math.abs(x(d.z) - x(d.a)))).attr('y', y(d.k)).attr('height', y.bandwidth()).attr('rx', 2).attr('fill', col(d)).attr('opacity', d.k === 'plan' || d.k === 'real' ? .9 : .75);
        if (i < D.length - 1) g.append('line').attr('x1', x(d.z)).attr('x2', x(d.z)).attr('y1', y(d.k) + y.bandwidth()).attr('y2', y(D[i + 1].k)).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '2 2');
        g.append('text').attr('class', 'lbl-strong').attr('x', x(Math.max(d.a, d.z)) + 6).attr('y', y(d.k) + y.bandwidth() / 2).attr('dy', '.35em')
          .text(d.k === 'plan' || d.k === 'real' ? `${f1(d.v)} km` : `${d.v > 0 ? '+' : '−'}${f1(Math.abs(d.v))}`);
      });
      readout('r-bridge', `tracé commun : la montre mesure <b>×${F('.2f')(M.gps_ratio)}</b> la longueur du tracé`);
      legend('l-bridge', [['', C('--series-avec'), 'calendrier'], ['', C('--down'), 'décision qui ajoute'], ['', C('--up'), 'décision qui retire'], ['', C('--warning'), 'terrain'], ['', C('--text-muted'), 'mesure']]);
    }
    // ---- text
    const B = Object.fromEntries(M.bridge.map(b => [b.k, b.v])), N = P_.camps.map((c, i) => Rl.camps[i].plan_km - c.km);
    const ahead = N.map((d, i) => [d, i]).filter(([d]) => d > 1.5), behind = N.map((d, i) => [d, i]).filter(([d]) => d < -1.5);
    const biv = d3.sum(M.biv, x => x.km), bivUp = d3.sum(M.biv, x => x.up);
    const decPlus = B.add + B.var, decMinus = -(B.ab + B.nd), mes = B.gps + B.noise;
    $('t-plan').textContent = `Le plan complet, jour de marge compris, faisait ${f1(P_.km_walk)} km et ${f0(P_.dplus)} m de dénivelé ; la traversée en a fait ${f1(B.real)} et ${f0(totDp)} m. Le dénivelé est presque identique : le relief prévu a bien été gravi, autrement. L’écart de distance n’est pas un excès de kilomètres. Les décisions en route se compensent : ${f1(decMinus)} km abandonnés (Tønnåsheia, Kitinden, Helvetestinden, Hermannsdalstinden, tour du lac) contre ${f1(decPlus)} km de substitutions et de variantes (Moltinden, Reine et l’arête de Reinebringen–Helvete, Gylttinden, chemins du sud). La recherche de bivouac ajoute ${f1(B.biv)} km, surtout à Bunes, et le reste (${f1(mes)} km) est de la mesure : sur le parcours commun, la montre compte ${f0((M.gps_ratio - 1) * 100)} % de plus que le tracé lissé. Sur l’avancement, les soirs des ${ahead.map(([, i]) => dateLbl(P_.camps[i].night)).join(' et ')} sont en avance sur la feuille de route (jusqu’à +${f0(d3.max(ahead, a => a[0]))} km) ; le bateau du J4 ramène l’avancement sur le plan. À partir du ${dateLbl(P_.camps[behind[0][1]].night)}, le retard est choisi : camp fixe à Sørvågen, tour du lac abandonné et jour de marge avancé pour la Støvla.`;
  }

  /* ---------- 14 · conclusion ---------- */
  function drawConcl() {
    const L = [
      ['Le sac ralentit, le danger arrive sans lui', `Le sac coûte ${fs0(sacS.pct)} % de temps à terrain égal, mais il rend l’allure plus régulière. Trois des quatre alertes de terrain ont eu lieu sans le sac, sur des sommets en trail, là où je me sentais le plus libre.`],
      ['Chaque pas est ordinaire, c’est l’enchaînement qui coûte', `Pris un par un, les tronçons suivent presque une loi normale. Mais dans un massif, les écarts vont dans le même sens et s’additionnent : l’incertitude sur le temps total passe de ± ${f0(EP.topo.agg.seg)} à ± ${f0(EP.topo.agg.massif)} min.`],

      ['La fatigue ne ralentit pas : elle fait renoncer', 'Aucun effet mesurable sur l’allure, mais les trois renoncements suivent tous de la fatigue ou du temps perdu juste avant. La fatigue se voit dans les décisions, pas sur la montre.'],
      ['Le risque s’est concentré à la fin', `${f1(lateRain / W_.total_rain * 100)} % de la pluie est tombée du J7 au J9, quand la réserve physique était au plus bas. Les trois incidents graves tombent dans cette fenêtre.`],
      ['Le terrain coté explique où tombent les alertes', `Les sorties exigeantes ou expertes concentrent toutes les alertes analysées. La cote DNT est le premier filtre de risque, avant la météo et la fatigue.`],
      ['La marge a transformé la pluie en simple attente', R.cf.margin ? `L’été 2026 a été plus arrosé que ${f0(R.cf.clim.pct_rain)} % des étés, mais la pluie est tombée une fois la traversée finie. Ce moment « gratuit » tient aussi à l’avance prise les J2–J3 : elle fait passer de ${f0(R.cf.margin.scen[0].free)} % à ${f0(R.cf.margin.scen[2].free)} % les mondes météo où la pluie ne coûte rien.` : ''],
      ['Planifier sur la moyenne, c’est sous-estimer la marge', `La loi normale sous-estime d’un facteur ${f0(pB / pN)} le risque d’une journée de plus de 10 h. Les écarts s’additionnent sur un même massif : la marge se calcule sur le seuil à 95 %, sommet par sommet.`],
    ];
    $('lessons').innerHTML = L.map(([h, p]) => `<li><h4>${h}</h4><p>${p}</p></li>`).join('');
    $('rules').innerHTML = [
      `<b>Marge horaire = seuil à 95 %</b>, pas la moyenne : environ ${hm(MC.blocs.day_p95[j3] - MC.blocs.day_p50[j3])} de plus sur une grosse journée de ${f0(MC.blocs.day_p50[j3])} h, et un départ en conséquence.`,
      '<b>Après une nuit de moins de 4 h, pas de sommet exposé</b> le lendemain : la décision se dégrade avant les jambes.',
      '<b>Sous la pluie, rester sous la cote « exigeant »</b> : roche mouillée, pierriers et barres rocheuses concentrent les queues.',
      '<b>Au premier passage hors de la bande, réévaluer</b> plutôt que forcer : le suivant a de bonnes chances d’être difficile aussi.',
      '<b>Prendre de l’avance tant qu’il fait beau</b> : chaque jour gagné tôt transforme une future pluie en simple attente au lieu d’une étape forcée avec le sac.',
    ].map((x, i) => `<li data-k="R${i + 1}"><span>${x}</span></li>`).join('');
  }

  /* ---------- hero · map card thumbnail (the real trace) ---------- */
  function drawMapThumb() {
    const svg = d3.select('#map-thumb'); if (svg.empty()) return;
    svg.selectAll('*').remove();
    const el = svg.node(), W = el.clientWidth || 240, H = el.clientHeight || 150;
    svg.attr('viewBox', `0 0 ${W} ${H}`);
    const T = R.trace, lat0 = d3.mean(T, p => p[1]) * Math.PI / 180;
    const pts = T.map(p => [p[0] * Math.cos(lat0), -p[1]]);
    const x = d3.scaleLinear().domain(d3.extent(pts, p => p[0])), y = d3.scaleLinear().domain(d3.extent(pts, p => p[1]));
    const sx = (W - 24) / (x.domain()[1] - x.domain()[0]), sy = (H - 24) / (y.domain()[1] - y.domain()[0]), s = Math.min(sx, sy);
    const ox = (W - s * (x.domain()[1] - x.domain()[0])) / 2, oy = (H - s * (y.domain()[1] - y.domain()[0])) / 2;
    const P = pts.map(p => [ox + (p[0] - x.domain()[0]) * s, oy + (p[1] - y.domain()[0]) * s]);
    // contour-like halo, then the trace coloured with / without the pack (as on the map)
    svg.append('path').attr('d', d3.line()(P)).attr('fill', 'none').attr('stroke', C('--accent')).attr('stroke-width', 7).attr('stroke-opacity', .08).attr('stroke-linejoin', 'round');
    for (let i = 1; i < P.length; i++) {
      if (Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]) > 18) continue;   // ferry / gap: no segment
      svg.append('line').attr('x1', P[i - 1][0]).attr('y1', P[i - 1][1]).attr('x2', P[i][0]).attr('y2', P[i][1])
        .attr('stroke', T[i][2] ? C('--series-avec') : C('--series-sans')).attr('stroke-width', 1.8).attr('stroke-linecap', 'round');
    }
    [[P[0], C('--up')], [P[P.length - 1], C('--text-primary')]].forEach(([p, c]) => svg.append('circle').attr('cx', p[0]).attr('cy', p[1]).attr('r', 3.6).attr('fill', c).attr('stroke', C('--bg')).attr('stroke-width', 1.5));
    svg.append('text').attr('class', 'lbl').attr('x', 8).attr('y', H - 8).text('N ↑');
  }

  /* ---------- 14 · luck vs decision (sketch) ---------- */
  function drawCF() {
    const CW = R.cf.weather, CP = R.cf.pace, CD = R.cf.dec;
    // (0) 30 summers + 1 200 start dates (real ERA5)
    const CL = R.cf.clim;
    if (CL) {
      {
        const Y = [...CL.years.map(y => ({ ...y, real: false })), { year: 2026, km: CL.real.km, rain: CL.real.rain, wet: CL.real.wet, mmkm: CL.real.mmkm, real: true }].sort((a, b) => a.rain - b.rain || a.year - b.year);
        const f = frame('c-cfy', { t: 18, r: 50, b: 40, l: 8 });
        const x = d3.scaleBand().domain(Y.map(y => y.year)).range([0, f.w]).padding(.22);
        const y = d3.scaleLinear().domain([0, d3.max(Y, v => v.rain) * 1.12]).nice().range([f.h, 0]);
        yGrid(f.g, y, f.w, 4, v => `${v} mm`);
        const col = d3.scaleLinear().domain([0, CL.med_rain, d3.max(Y, v => v.rain)]).range([C('--up'), C('--text-muted'), C('--down')]).interpolate(d3.interpolateLab);
        f.g.selectAll('.yb').data(Y).join('path').attr('d', v => barPath(x(v.year), y(0), x.bandwidth(), y(Math.max(v.rain, .4)), 1.5))
          .attr('fill', v => v.real ? C('--warning') : col(v.rain)).attr('fill-opacity', v => v.real ? 1 : .7);
        f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(CL.med_rain)).attr('y2', y(CL.med_rain)).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3');
        axTag(f.g, f.w + 2, y(CL.med_rain), `méd ${f0(CL.med_rain)}`);
        f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).tickSize(0).tickPadding(6).tickFormat(v => v === 2026 ? '2026' : (f.narrow ? '' : `’${String(v).slice(2)}`)))
          .selectAll('text').attr('transform', 'rotate(-60)').attr('text-anchor', 'end').attr('dx', '-.4em').attr('dy', '.2em').style('fill', v => v === 2026 ? C('--warning') : null).style('font-weight', v => v === 2026 ? 700 : null);
        const r = Y.find(v => v.real);
        f.g.append('text').attr('class', 'lbl-ink').attr('x', x(2026) + x.bandwidth() / 2).attr('y', y(r.rain) - 8).attr('text-anchor', 'middle').text('2026');
        hover(f.g.selectAll('.yh').data(Y).join('rect').attr('class', 'hit').attr('x', v => x(v.year)).attr('width', x.step()).attr('y', 0).attr('height', f.h),
          v => `<b>Été ${v.year}${v.real ? ' (réel)' : ''}</b>${row('pluie 14–22 juin', `${f1(v.rain)} mm`)}${row('jours de pluie (≥ 1 mm)', v.wet)}`);
        legend('l-cfy', [['', C('--warning'), 'été 2026 (réel)'], ['', C('--up'), 'été plus sec'], ['', C('--down'), 'été plus arrosé'], ['dash', '', 'médiane des 30 étés']]);
        readout('r-cfy', `pluie <b>P${f0(CL.pct_rain)}</b> · jours de pluie <b>P${f0(CL.pct_wet)}</b>`);
      }
      {
        const S = CL.starts_rain, tot = d3.sum(S.hist);
        const f = frame('c-cfs', { t: 18, r: 50, b: 34, l: 8 });
        const x = d3.scaleLinear().domain([0, S.edges[S.edges.length - 1]]).range([0, f.w]);
        const y = d3.scaleLinear().domain([0, d3.max(S.hist) / tot * 1.12]).range([f.h, 0]);
        yGrid(f.g, y, f.w, 4, v => `${f0(v * 100)} %`);
        xAxis(f.g, x, f.h, 6, v => `${v} mm`);
        axTitle(f.g, 'pluie cumulée sur 9 jours, par date de départ', 0, f.h + 30);
        const bins = S.hist.map((n, i) => ({ n, a: S.edges[i], b: S.edges[i] + 2 }));
        f.g.selectAll('.sb').data(bins).join('path').attr('d', d => barPath(x(d.a) + .5, y(0), Math.max(1, x(d.b) - x(d.a) - 1.5), y(d.n / tot), 1.5))
          .attr('fill', d => d.b <= CL.real.rain ? C('--up') : d.a > CL.real.rain ? C('--down') : C('--warning')).attr('fill-opacity', .6);
        const xr = x(CL.real.rain);
        f.g.append('line').attr('x1', xr).attr('x2', xr).attr('y1', -6).attr('y2', f.h).attr('stroke', C('--warning')).attr('stroke-width', 1.6);
        f.g.append('text').attr('class', 'lbl-ink').attr('x', xr + 6).attr('y', 4).text(`2026 · P${f0(S.pct)}`);
        hover(f.g.selectAll('.sh2').data(bins).join('rect').attr('class', 'hit').attr('x', d => x(d.a)).attr('width', d => x(d.b) - x(d.a)).attr('y', 0).attr('height', f.h),
          d => `<b>${d.a} à ${d.b} mm</b>${row('départs', `${d.n} / ${tot}`)}`);
        legend('l-cfs', [['', C('--up'), 'départ plus sec'], ['', C('--down'), 'plus arrosé'], ['ln', C('--warning'), 'départ réel (14 juin 2026)']]);
        readout('r-cfs', `moy. <b>${f1(S.mean)} mm</b> · 2026 <b>${f1(CL.real.rain)} mm</b>`);
      }
    }
    // (f) declared factors: endured vs chosen
    const FA = R.cf.fact;
    if (FA) {
      const groups = ['subi', 'choisi'], lab = { subi: 'Subis · environnement', choisi: 'Choisis · préparation et conduite' };
      const f = frame('c-cff', { t: 10, r: 20, b: 26, l: $('c-cff').clientWidth < 560 ? 120 : 230 });
      const mx = d3.max(groups, g => FA.filter(x => x.ctrl === g).length);
      const x = d3.scaleLinear().domain([-mx, mx]).range([0, f.w]);
      const y = d3.scaleBand().domain(groups).range([0, f.h]).padding(.3);
      f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(8).tickSize(-f.h).tickFormat('')).lower();
      xAxis(f.g, x, f.h, 8, v => Math.abs(v));
      f.g.append('line').attr('class', 'zero').attr('x1', x(0)).attr('x2', x(0)).attr('y1', 0).attr('y2', f.h);
      groups.forEach(g => {
        const ag = FA.filter(v => v.ctrl === g && v.sens === 'aggravant'), at = FA.filter(v => v.ctrl === g && v.sens !== 'aggravant');
        const yy = y(g);
        f.g.append('text').attr('class', 'lbl-strong').attr('x', -10).attr('y', yy + y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(f.m.l > 200 ? lab[g] : g);
        // one block per factor, so each can be hovered
        [[ag, -1, C('--down')], [at, 1, C('--up')]].forEach(([arr, sgn, col]) => arr.forEach((v, i) => {
          const x0 = sgn > 0 ? x(i) : x(-(i + 1));
          const b = f.g.append('rect').attr('x', x0 + 1).attr('y', yy).attr('width', Math.max(1, x(1) - x(0) - 2)).attr('height', y.bandwidth()).attr('rx', 2).attr('fill', col).attr('fill-opacity', .72);
          b.on('pointermove', ev => showTip(ev, `<b>${v.id.replace(/_/g, ' ')}</b>${row('sens', v.sens)}${row('nature', v.ctrl)}<div class="r" style="display:block;margin-top:4px">${v.txt}</div>`)).on('pointerleave', hideTip);
        }));
        f.g.append('text').attr('class', 'lbl tagt').attr('x', x(-ag.length) - 6).attr('y', yy + y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(ag.length);
        f.g.append('text').attr('class', 'lbl tagt').attr('x', x(at.length) + 6).attr('y', yy + y.bandwidth() / 2).attr('dy', '.35em').text(at.length);
      });
      legend('l-cff', [['', C('--down'), 'aggravant'], ['', C('--up'), 'atténuant']]);
      const cnt = (c, s) => FA.filter(v => v.ctrl === c && (s === 'aggravant' ? v.sens === 'aggravant' : v.sens !== 'aggravant')).length;
      readout('r-cff', `choisis <b>${cnt('choisi', 'atténuant')}</b> atténuants / <b>${cnt('choisi', 'aggravant')}</b> aggravants`);
    }
    // (a) distribution of exposure over the 362 880 weather orders
    {
      const f = frame('c-cfw', { t: 18, r: 50, b: 34, l: 8 });
      const dist = CW.km.dist, tot = d3.sum(dist, d => d[1]);
      const x = d3.scaleLinear().domain([0, CW.total_hard]).range([0, f.w]);
      const y = d3.scaleLinear().domain([0, d3.max(dist, d => d[1] / tot) * 1.15]).range([f.h, 0]);
      yGrid(f.g, y, f.w, 4, v => `${f0(v * 100)} %`);
      xAxis(f.g, x, f.h, 6, v => `${v} km`);
      axTitle(f.g, 'km exigeants ou experts parcourus un jour de pluie', 0, f.h + 30);
      const bw = Math.max(2, f.w / 70);
      f.g.selectAll('.cb').data(dist).join('path').attr('d', d => barPath(x(d[0]) - bw / 2, y(0), bw, y(d[1] / tot), 1.5))
        .attr('fill', d => Math.abs(d[0] - CW.km.real) < .05 ? C('--warning') : d[0] < CW.km.real ? C('--up') : C('--down')).attr('fill-opacity', d => Math.abs(d[0] - CW.km.real) < .05 ? 1 : .55);
      const xr = x(CW.km.real);
      f.g.append('line').attr('x1', xr).attr('x2', xr).attr('y1', -6).attr('y2', f.h).attr('stroke', C('--warning')).attr('stroke-width', 1.6);
      f.g.append('text').attr('class', 'lbl-ink').attr('x', xr + 6).attr('y', 4).text(`réel ${f1(CW.km.real)} km`);
      const xm = x(CW.km.mean);
      f.g.append('line').attr('x1', xm).attr('x2', xm).attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '4 3');
      hover(f.g.selectAll('.ch').data(dist).join('rect').attr('class', 'hit').attr('x', d => x(d[0]) - 5).attr('width', 10).attr('y', 0).attr('height', f.h),
        d => `<b>${f1(d[0])} km exposés</b>${row('part des ordres', `${f2(d[1] / tot * 100)} %`)}`);
      legend('l-cfw', [['', C('--up'), 'placement plus prudent'], ['', C('--down'), 'placement plus exposé'], ['ln', C('--warning'), 'mon placement réel'], ['dash', '', 'placement au hasard (moyenne)']]);
      readout('r-cfw', `mieux que <b>${f0(CW.km.rank.above)} %</b> du hasard · moy. <b>${f1(CW.km.mean)} km</b>`);
    }
    // (b) the margin: share of the 1 200 weather worlds where rain costs nothing, by margin level
    const MG = R.cf.margin;
    if (MG) {
      const Sc = MG.scen;
      const f = frame('c-cfb', { t: 26, r: 16, b: 30, l: $('c-cfb').clientWidth < 520 ? 108 : 150 });
      const narrowM = f.w < 420, barW = narrowM ? f.w - 40 : f.w * .5;
      const y = d3.scaleBand().domain(Sc.map(d => d.key)).range([0, f.h]).padding(narrowM ? .5 : .38);
      const x1 = d3.scaleLinear().domain([0, 100]).range([0, barW]);
      f.g.append('text').attr('class', 'ax-title').attr('y', -12).text(f.w < 300 ? 'mondes où la pluie ne coûte rien' : 'part des 1 200 mondes où la pluie ne coûte rien');
      f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x1).ticks(4).tickSize(-f.h).tickFormat('')).lower();
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x1).ticks(4).tickSize(0).tickPadding(8).tickFormat(v => `${v} %`));
      const lbl = { plan: f.m.l > 120 ? 'Marge du plan · 1 j' : 'Plan · 1 j', sans_avance: f.m.l > 120 ? 'Sans l’avance · 2 j' : 'Sans avance · 2 j', reel: f.m.l > 120 ? 'Réel, avance · 3 j' : 'Réel · 3 j' };
      f.g.selectAll('.ml').data(Sc).join('text').attr('class', d => d.key === 'reel' ? 'lbl-ink' : 'lbl-strong').attr('x', -10).attr('y', d => y(d.key) + y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(d => lbl[d.key]);
      const colS = d => d.key === 'reel' ? C('--up') : d.key === 'plan' ? C('--down') : C('--text-muted');
      f.g.selectAll('.b1').data(Sc).join('rect').attr('x', 0).attr('y', d => y(d.key)).attr('height', y.bandwidth()).attr('width', d => x1(d.free)).attr('rx', 2).attr('fill', colS).attr('fill-opacity', .75);
      f.g.selectAll('.t1').data(Sc).join('text').attr('class', 'lbl-ink tagt').attr('x', d => x1(d.free) + 6).attr('y', d => y(d.key) + y.bandwidth() / 2).attr('dy', '.35em').text(d => `${f0(d.free)} %`);
      const tx = narrowM ? 0 : barW + 58;
      const ty = d => narrowM ? y(d.key) + y.bandwidth() + 12 : y(d.key) + y.bandwidth() / 2 - 6;
      const t26 = d => d.r2026.wet_moves ? `2026 : ${d.r2026.wet_moves} étape${d.r2026.wet_moves > 1 ? 's' : ''} mouillée${d.r2026.wet_moves > 1 ? 's' : ''}` : '2026 : aucune étape mouillée';
      f.g.selectAll('.t2').data(Sc).join('text').attr('class', 'lbl tagt').attr('x', tx).attr('y', ty).attr('dy', '.35em').text(d => f.w < 300 ? `${f1(d.mean_forced)} km · 2026 : ${d.r2026.wet_moves || 'aucune'} mouillée${d.r2026.wet_moves > 1 ? 's' : ''}` : `${f1(d.mean_forced)} km forcés en moy.${narrowM ? ` · ${t26(d)}` : ''}`);
      if (!narrowM) f.g.selectAll('.t3').data(Sc).join('text').attr('class', d => d.r2026.wet_moves ? 'lbl tagt' : 'lbl-ink tagt').attr('x', tx).attr('y', d => ty(d) + 15).attr('dy', '.35em').style('fill', d => d.r2026.wet_moves ? C('--down') : C('--up')).text(t26);
      hover(f.g.selectAll('.mh').data(Sc).join('rect').attr('class', 'hit').attr('x', -f.m.l).attr('width', f.w + f.m.l).attr('y', d => y(d.key) - 4).attr('height', y.bandwidth() + 16),
        d => `<b>${d.label}</b>${row('étapes avec le sac', `${d.n_moves} en 9 jours`)}${row('mondes sans étape mouillée', `${f1(d.free)} %`)}${row('mondes avec terrain exigeant mouillé', `${f1(d.any_hard)} %`)}${row('km exigeants forcés (moy. · P90)', `${f1(d.mean_forced)} · ${f1(d.p90_forced)}`)}${row('2026', d.r2026.wet_moves ? `${d.r2026.wet_moves} étape(s), ${f1(d.r2026.forced)} km` : 'aucune')}`);
      legend('l-cfb', [['', C('--down'), 'marge du plan'], ['', C('--text-muted'), 'sans l’avance des J2–J3'], ['', C('--up'), 'réel, avance prise']]);
      const P = Sc.find(d => d.key === 'plan'), Rl = Sc.find(d => d.key === 'reel');
      readout('r-cfb', `pluie gratuite <b>${f0(P.free)} → ${f0(Rl.free)} %</b> · 1 200 mondes`);
    }
    // (c) pace luck: each real day inside its simulated range
    {
      const f = frame('c-cfp', { t: 14, r: 50, b: 26, l: 8 });
      const x = d3.scaleBand().domain(CP.days).range([0, f.w]).padding(.5);
      const y = d3.scaleLinear().domain([0, 100]).range([f.h, 0]);
      yGrid(f.g, y, f.w, 4, v => `P${v}`);
      xAxis(f.g, x, f.h, null, dayLbl);
      [[0, 25, C('--up')], [75, 100, C('--down')]].forEach(([a, b, c]) => f.g.append('rect').attr('x', 0).attr('width', f.w).attr('y', y(b)).attr('height', y(a) - y(b)).attr('fill', c).attr('opacity', .06));
      f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(50)).attr('y2', y(50)).attr('stroke', C('--text-muted')).attr('stroke-dasharray', '4 3');
      const g = f.g.selectAll('.pd').data(CP.days.map((d, i) => ({ d, r: CP.rank[i], rn: CP.rank_n[i], real: CP.real[i], p5: CP.p5[i], p50: CP.p50[i], p95: CP.p95[i] }))).join('g').attr('transform', d => `translate(${x(d.d) + x.bandwidth() / 2},0)`);
      g.append('line').attr('y1', y(50)).attr('y2', d => y(d.r)).attr('stroke', d => d.r > 50 ? C('--down') : C('--up')).attr('stroke-width', 2);
      g.append('circle').attr('cy', d => y(d.r)).attr('r', 5).attr('fill', d => d.r > 50 ? C('--down') : C('--up')).attr('stroke', C('--bg')).attr('stroke-width', 1.5);
      g.append('text').attr('class', 'lbl tagt').attr('y', d => y(d.r) + (d.r > 50 ? -10 : 16)).attr('text-anchor', 'middle').text(d => `P${f0(d.r)}`);
      hover(g.append('rect').attr('class', 'hit').attr('x', -x.step() / 2).attr('width', x.step()).attr('y', 0).attr('height', f.h),
        d => `<b>${dayLbl(d.d)} · ${hm(d.real)} de marche</b>${row('rang parmi 5 000', `P${f0(d.r)}`)}${row('fourchette simulée P5–P95', `${hm(d.p5)} – ${hm(d.p95)}`)}${row('médiane simulée', hm(d.p50))}`);
      legend('l-cfp', [['', C('--up'), 'plus rapide que la médiane simulée (aléa favorable)'], ['', C('--down'), 'plus lent (aléa défavorable)']]);
      readout('r-cfp', `jours favorables <b>${CP.rank.filter(r => r < 50).length}</b> / 9`);
    }
    // (d) decision × outcome matrix
    const I = CD.items, qL = q => q >= .5 ? 'bonne' : q <= -.2 ? 'risquée' : 'neutre';
    {
      const f = frame('c-cfd', { t: 14, r: 14, b: 34, l: 34 });
      const x = d3.scaleLinear().domain([-1.25, 1.25]).range([0, f.w]), y = d3.scaleLinear().domain([-1.3, 1.3]).range([f.h, 0]);
      [[-1.25, 0, 0, 1.3, C('--warning'), 'CHANCE'], [0, 1.25, 0, 1.3, C('--up'), 'MÉRITÉ'], [-1.25, 0, -1.3, 0, C('--down'), 'CONSÉQUENCE'], [0, 1.25, -1.3, 0, C('--series-avec'), 'MALCHANCE']]
        .forEach(([a, b, c, d, col, t], i) => {
          f.g.append('rect').attr('x', x(a)).attr('width', x(b) - x(a)).attr('y', y(d)).attr('height', y(c) - y(d)).attr('fill', col).attr('opacity', .06);
          f.g.append('text').attr('class', 'qd-q').attr('fill', col).attr('x', i % 2 ? f.w - 6 : 6).attr('y', i < 2 ? 14 : f.h - 8).attr('text-anchor', i % 2 ? 'end' : 'start').text(t);
        });
      f.g.append('line').attr('x1', x(0)).attr('x2', x(0)).attr('y1', 0).attr('y2', f.h).attr('stroke', C('--text-muted'));
      f.g.append('line').attr('x1', 0).attr('x2', f.w).attr('y1', y(0)).attr('y2', y(0)).attr('stroke', C('--text-muted'));
      f.g.append('line').attr('x1', x(-1.2)).attr('x2', x(1.2)).attr('y1', y(CD.icpt + CD.slope * -1.2)).attr('y2', y(CD.icpt + CD.slope * 1.2)).attr('stroke', C('--text-primary')).attr('stroke-dasharray', '5 4').attr('opacity', .7);
      f.g.append('g').attr('class', 'axis').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).tickValues([-1, 0, 1]).tickSize(0).tickPadding(8).tickFormat(v => ({ '-1': 'risquée', 0: 'neutre', 1: 'bonne' })[v]));
      f.g.append('g').attr('class', 'axis').call(d3.axisLeft(y).tickValues([-1, 0, 1]).tickSize(0).tickPadding(6).tickFormat(F('+d')));
      axTitle(f.g, 'qualité de la décision, ex ante →', f.w, f.h + 30, 'end');
      axTitle(f.g, 'résultat ↑', 4, -4);
      // small jitter so stacked decisions stay readable
      const seen = {}; const J = I.map(d => { const k = `${d.q}|${d.out}`; seen[k] = (seen[k] || 0) + 1; return { ...d, jx: (seen[k] - 1) * .09, jy: (seen[k] - 1) * -.07 }; });
      const g = f.g.selectAll('.dp').data(J).join('g').attr('transform', d => `translate(${x(d.q - d.jx)},${y(d.out + d.jy)})`);
      g.append('circle').attr('r', 7).attr('fill', d => d.kind === 'P' ? C('--accent') : C('--series-sans')).attr('fill-opacity', .85).attr('stroke', C('--bg')).attr('stroke-width', 1.5);
      g.append('text').attr('class', 'lbl').attr('dy', '.35em').attr('text-anchor', 'middle').style('fill', '#0b1015').style('font-size', '8.5px').style('font-weight', 700).text(d => d.day.slice(1));
      if (!f.narrow) g.filter(d => d.luck > .6 || d.luck < -.6).append('text').attr('class', 'lbl-strong').attr('x', 11).attr('dy', '.35em').text(d => d.txt.length > 34 ? `${d.txt.slice(0, 33)}…` : d.txt);
      hover(g.append('circle').attr('class', 'hit').attr('r', 12),
        d => `<b>${d.day} · ${d.txt}</b>${row('type', d.kind === 'P' ? 'prudente' : 'engagée')}${row('drapeaux ex ante', d.flags.length ? d.flags.length : 'aucun')}${row('qualité', `${fs2(d.q)} (${qL(d.q)})`)}${row('résultat', fs1(d.out))}${row('part de chance', fs2(d.luck))}`);
      readout('r-cfd', `ρ <b>${f2(CD.rho)}</b> · R² <b>${f2(CD.r2)}</b>`);
    }
    // (e) luck per decision (residual)
    {
      const S = [...I].sort((a, b) => b.luck - a.luck);
      const f = frame('c-cfl', { t: 10, r: 44, b: 26, l: $('c-cfl').clientWidth < 420 ? 130 : 220 });
      const x = d3.scaleLinear().domain([-1.3, 1.3]).range([0, f.w]);
      const y = d3.scaleBand().domain(S.map((d, i) => i)).range([0, f.h]).padding(.3);
      f.g.append('g').attr('class', 'gridl').attr('transform', `translate(0,${f.h})`).call(d3.axisBottom(x).ticks(5).tickSize(-f.h).tickFormat('')).lower();
      xAxis(f.g, x, f.h, 5, F('+.1f'));
      f.g.append('line').attr('class', 'zero').attr('x1', x(0)).attr('x2', x(0)).attr('y1', 0).attr('y2', f.h);
      const r = f.g.selectAll('.lr').data(S).join('g').attr('transform', (d, i) => `translate(0,${y(i)})`);
      r.append('text').attr('class', 'lbl-strong').attr('x', -8).attr('y', y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', 'end').text(d => { const t = `${d.day} · ${d.txt}`, n = f.m.l > 200 ? 30 : 18; return t.length > n ? `${t.slice(0, n - 1)}…` : t; });
      r.append('rect').attr('x', d => x(Math.min(0, d.luck))).attr('width', d => Math.abs(x(d.luck) - x(0))).attr('height', y.bandwidth()).attr('rx', 2)
        .attr('fill', d => d.luck >= 0 ? C('--up') : C('--down')).attr('fill-opacity', .75);
      r.append('text').attr('class', 'lbl tagt').attr('x', d => x(d.luck) + (d.luck >= 0 ? 5 : -5)).attr('y', y.bandwidth() / 2).attr('dy', '.35em').attr('text-anchor', d => d.luck >= 0 ? 'start' : 'end').text(d => fs2(d.luck));
      hover(r.append('rect').attr('class', 'hit').attr('x', -f.m.l).attr('width', f.w + f.m.l + 40).attr('height', y.step()),
        d => `<b>${d.day} · ${d.txt}</b>${row('résultat constaté', d.res)}${row('part de chance', fs2(d.luck))}`);
    }
    // grid table
    const FL = { nuit: 'nuit courte', exig: 'cote exigeante', expert: 'cote experte', tard: 'tard / temps perdu', pluie: 'pluie', vent: 'vent > normale', neige: 'neige', brouillard: 'brouillard' };
    $('dec-table').innerHTML = `<thead><tr><th>Jour</th><th>Décision</th><th>Type</th><th>Drapeaux connus au moment</th><th class="n">Qualité</th><th>Résultat constaté</th><th class="n">Rés.</th><th class="n">Chance</th></tr></thead><tbody>${I.map(d => `<tr><td class="mono">${d.day}</td><td>${d.txt}</td><td class="nw"><span class="dot" style="background:${d.kind === 'P' ? C('--accent') : C('--series-sans')}"></span>${d.kind === 'P' ? 'prudente' : 'engagée'}</td><td>${d.flags.length ? d.flags.map(k => `<span class="flag">${FL[k]}</span>`).join('') : '<span class="muted">aucun</span>'}</td><td class="n">${fs2(d.q)}</td><td class="muted">${d.res}</td><td class="n">${fs1(d.out)}</td><td class="n" style="color:${d.luck >= 0 ? 'var(--up)' : 'var(--down)'}">${fs2(d.luck)}</td></tr>`).join('')}</tbody>`;
    const real = CW.blocks[CW.blocks.length - 1], worst = CW.blocks.reduce((a, b) => b.km > a.km ? b : a);
    const lucky = I.reduce((a, b) => b.luck > a.luck ? b : a);
    const fav = CP.rank.filter(r => r < 50).length;
    if (CL) $('cf-bilan').innerHTML = [
      ['Chance · pluie', `P${f0(CL.pct_rain)}`, `été 2026 plus arrosé que ${f0(CL.pct_rain)} % des 30 étés : défavorable`],
      ['Chance · jours de pluie', `P${f0(CL.pct_wet)}`, `${CL.real.wet} jours, comme un été normal : pluie concentrée`],
      ['Chance · aléa d’allure', `${fav} / 9`, 'journées plus rapides que la médiane simulée'],
      ['Décision · marge', MG ? `${f0(MG.scen[0].free)} → ${f0(MG.scen[2].free)} %` : '–', 'mondes où la pluie ne coûte rien, de la marge du plan à l’avance prise'],
      ['Décision · grille', `R² ${f2(CD.r2)}`, 'part des résultats expliquée par la qualité ex ante'],
    ].map(([k, b, t]) => `<div><span class="kl">${k}</span><b>${b}</b><span>${t}</span></div>`).join('');
    const MP = MG && MG.scen[0], MR = MG && MG.scen[2];
    $('t-cf').textContent = CL && MG
      ? `La chance a joué deux fois. Contre moi : l’été 2026 a été plus arrosé que ${f0(CL.pct_rain)} % des 30 étés. Pour moi : la pluie est arrivée une fois la traversée finie, quand fixer le camp à Sørvågen ne coûtait rien. Plus tôt, à Bunes ou à Horseid, attendre aurait voulu dire perdre une étape avec un seul jour de marge, ou marcher sous la pluie avec le sac. Mais ce moment « gratuit » doit aussi beaucoup à une décision : l’avance prise les J2–J3. Sur 1 200 mondes météo réels, la pluie ne coûte rien dans ${f0(MP.free)} % des cas avec la marge du plan, et dans ${f0(MR.free)} % avec l’avance prise ; le terrain exigeant parcouru sous la pluie avec le sac passe de ${f1(MP.mean_forced)} à ${f1(MR.mean_forced)} km en moyenne. En 2026, la marge du plan aurait forcé ${MP.r2026.wet_moves} étapes sous la pluie. Ensuite, sur place, l’adaptation est restée partielle : les sommets exigeants ont continué sous la pluie. Dans la grille, la qualité ex ante explique environ ${f0(CD.r2 * 100)} % des résultats. La Støvla tombe dans « conséquence ».`
      : '';
    $('cf-next').innerHTML = [
      '<b>Trois points ERA5 au lieu d’un</b> : rejouer chaque jour sur la zone de ses sorties (nord, centre, sud), et passer de la pluie journalière à la pluie pendant les heures de marche.',
      '<b>Prévisions consultées sur le moment</b> : la décision du camp fixe repose sur elles ; juger chaque décision avec la météo annoncée, pas avec celle qui est tombée.',
      '<b>Référence non adaptée : le plan initial (GPX)</b> : son exposition sous la météo réelle de 2026 mesurera directement ce que l’adaptation aux prévisions a apporté ; sous les 1 200 mondes, elle donnera la chance pure. Avec les sorties de secours, on chiffrera aussi le coût des options non prises.',
      '<b>Plus de décisions, notes validées</b> : compléter la grille (choix de bivouac, horaires, itinéraires) et valider drapeaux et résultats jour par jour.',
    ].map((x, i) => `<li data-k="A${i + 1}"><span>${x}</span></li>`).join('');
  }

  /* ---------- draw all, redraw on resize ---------- */
  const charts = [drawMapThumb, drawCandles, drawTerrain, drawTools, drawDist, drawRoll, drawAcf, drawSens, drawHrv, drawWx, drawPersist, () => drawMc(false), drawScatter, drawPlanCharts, drawCF];
  function drawAll() { charts.forEach(fn => { try { fn(); } catch (e) { console.error(fn.name, e); } }); }
  drawTail(); drawIndex(); drawPlan(); drawConcl(); drawAll(); initMc();
  let lastW = innerWidth, t = 0;
  addEventListener('resize', () => { if (Math.abs(innerWidth - lastW) < 8) return; lastW = innerWidth; clearTimeout(t); t = setTimeout(drawAll, 150); });
  matchMedia('(prefers-color-scheme: light)').addEventListener?.('change', () => { drawAll(); drawTail(); drawIndex(); });
})();
